(function(w){var a=w.BVC_PASSAGE_RESEARCH_CONTENT=w.BVC_PASSAGE_RESEARCH_CONTENT||[];[{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"EXODUS_01_15_22_READABLE_WORBS_v0.1_CANDIDATE","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/EXODUS_01_15_22_READABLE_WORBS_v0.1_CANDIDATE.md","sourceSha256":"2c5c5b9c92d362d517520c00392c8c0072e043f50d21a9c74ddf4e6ca6f922ed","passage":{"book":"exo","chapter":1,"v1":15,"v2":22,"ref":"출애굽기 1:15–22"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"왕의 명령보다 생명을 높인 두 사람","overview":["바로는 이스라엘을 강제노동으로 약화시키려 했으나 오히려 그들이 더 번성하자, 이번에는 태어나는 남자아이의 생명을 끊으려 한다. 그러나 왕의 명령을 받은 산파 십브라와 부아는 하나님을 경외하여 아이들을 살린다. 출애굽기는 이 두 사람의 작지만 결정적인 저항을 통해, 생명을 지키는 경외가 제국의 명령과 충돌하는 순간을 보여 준다. 이야기는 승리로 끝나지 않는다. 바로가 살해 명령을 온 백성에게 확대하기 때문이다. 그렇게 이 단락은 모세의 탄생이 얼마나 위태로운 시대에 놓여 있는지를 준비한다."],"centralMessage":"출애굽기 1:15–22는 누가 가장 큰 힘을 지녔는지를 비교하는 이야기가 아니다. 누구의 명령을 최종적인 것으로 받아들이는가를 묻는 이야기다. 왕은 아이들의 운명을 결정할 수 있다고 여겼지만, 이름 있는 두 산파는 하나님을 경외하여 그 명령을 따르지 않았다. 그들이 지킨 생명은 단지 한 번의 용감한 행위로 끝나지 않는다. 하나님이 이어 가시는 백성의 역사 안에 놓인다.","literaryStructure":[{"v1":15,"v2":16,"title":"이름 없는 왕, 이름이 남은 산파들"},{"v1":17,"v2":18,"title":"두려움의 질서가 뒤집히다"},{"v1":19,"v2":19,"title":"산파들의 대답과 서술자의 침묵"},{"v1":20,"v2":21,"title":"하나님이 좋게 여기신 것과 계속되는 번성"},{"v1":22,"v2":22,"title":"은밀한 살해에서 공개적 명령으로"}],"sections":[{"id":"exo1-15-16","v1":15,"v2":16,"title":"이름 없는 왕, 이름이 남은 산파들","paragraphs":["앞 단락에서 바로는 이스라엘의 번성을 국가적 위협으로 규정하고 고된 노동을 부과했다(1:8–14). 그러나 12절은 그들이 학대를 받을수록 더 많아졌다고 말한다. 15절에 이르면 탄압의 대상이 노동하는 어른들에서 이제 막 세상에 태어나는 아이들로 옮겨간다. 권력은 사람의 현재 노동을 통제하는 데서 그치지 않고, 그 민족의 미래 자체를 없애려 한다.","화자는 애굽 왕의 개인 이름을 알려 주지 않는다. 반대로 히브리 산파 두 사람의 이름은 또렷하게 적는다. 십브라와 부아다. 당대의 사회적 지위와 힘을 기준으로 보면 왕과 산파는 비교하기 어려웠을 것이다. 그러나 이야기의 중심은 군사력이나 궁정의 위엄이 아니라, 왕의 뜻을 거슬러 생명을 보전한 두 사람에게로 옮겨간다. 이 이름의 대비는 본문이 펼치는 문학적 역전이다. 권력자는 이름 없이 남고, 생명을 지킨 사람들은 이름으로 기억된다.","두 이름이 나왔다고 해서 이스라엘 전체에 산파가 오직 둘뿐이었다고 단정할 수는 없다. Tyndale Open Study Notes는 두 사람이 더 큰 산파 집단을 대표했을 가능성을 제시한다. 하지만 이것은 가능한 역사적 설명이지, 본문이 직접 밝힌 조직 체계는 아니다. 여기서 확실한 것은 왕이 십브라와 부아에게 살해 명령을 내렸고, 화자가 그들의 이름을 보존했다는 사실이다.","왕의 명령은 남아라면 죽이고 여아라면 살려 두라는 것이었다. 16절의 히브리어 표현 ‘두 돌 위를 보다’(עַל־הָאָבְנָיִם)는 출산 과정의 특정 기구 또는 출산 상황을 가리키는 난해한 표현이다. 흔히 출산 의자 또는 출산대로 설명하지만 물건의 정확한 형태를 확정할 수는 없다. 이 표현의 핵심은 왕이 산파들이 출산 현장에 가장 가까이 있다는 점을 살인에 이용하려 했다는 것이다. 생명을 돕는 손을 죽음의 도구로 바꾸려 한 셈이다."]},{"id":"exo1-17-18","v1":17,"v2":18,"title":"두려움의 질서가 뒤집히다","paragraphs":["17절의 첫 전환은 짧지만 강하다. ‘그러나 산파들은 하나님을 두려워하여’라는 진술이 왕의 명령과 정면으로 맞선다. 이 대목에서 ‘두려워하다’는 동사 ירא(야레)의 의미는 공포에 질렸다는 데 있지 않다. 누구의 권위를 궁극적으로 인정하는가 하는 경외의 문제다. 왕에게 항명하면 생명이 위험해질 수 있는 상황에서 산파들은 보이지 않는 하나님의 뜻을 더 무겁게 받아들인다.","서술은 그들의 내면을 길게 상상하지 않는다. 다만 명령과 행동의 대조를 분명히 제시한다. 왕은 남자아이들을 죽이라 했지만 산파들은 그들을 살렸다. 여기에는 ‘하지 않았다’는 소극적 거부뿐 아니라 아이들의 생명을 보전했다는 적극적인 결과가 담겨 있다. 인간의 명령이 하나님의 생명 보전 뜻과 충돌할 때 두 사람은 행동으로 경계선을 그었다.","바로는 즉시 그들을 불러 묻는다. ‘어찌하여 이같이 하여 남자아이들을 살렸느냐?’ 왕의 질문 자체가 그 명령이 실패했음을 드러낸다. 대제국의 최고 권력자가 가장 약해 보이는 여성들에게 실패의 이유를 묻는 장면은 출애굽기의 권력 역전을 한층 또렷하게 보여 준다."]},{"id":"exo1-19-19","v1":19,"v2":19,"title":"산파들의 대답과 서술자의 침묵","paragraphs":["산파들은 히브리 여자들이 애굽 여자들과 달리 ‘생기가 있어서’ 산파가 오기 전에 아이를 낳는다고 대답한다. 이 대답을 읽을 때에는 두 가지를 구분해야 한다. 첫째, 산파들이 실제로 이렇게 말했다는 것은 본문의 진술이다. 둘째, 그 설명이 모든 출산 상황에 대한 정확한 보고였는지, 왕을 속이기 위한 답변이었는지는 본문이 직접 판정하지 않는다.","Tyndale 주석은 산파들이 자신의 참된 동기를 바로에게 모두 말하지 않았을 가능성을 적극적으로 논한다. 반면 unfoldingWord의 번역주는 이 대답의 논리, 곧 히브리 여인들이 활력이 있어서 산파가 도착하기 전에 출산한다는 진술이 어떻게 연결되는지를 설명한다. 따라서 독자에게는 산파의 대답을 미화하여 무조건적 거짓말의 모범으로 만들거나, 반대로 구체적인 출산 속도를 역사적 사실로 확정하지 않는 태도가 필요하다.","핵심은 본문이 그들을 칭찬하는 이유다. 서술자는 그들이 말을 교묘하게 잘했기 때문이라고 말하지 않는다. 반복하여 강조하는 이유는 ‘하나님을 경외했기 때문’이다(17, 21절). 본문은 그들의 모든 표현에 대한 일반적 윤리 규칙을 제시하기보다, 생명을 파괴하라는 명령 앞에서 하나님을 경외한 행동을 조명한다."]},{"id":"exo1-20-21","v1":20,"v2":21,"title":"하나님이 좋게 여기신 것과 계속되는 번성","paragraphs":["이제 이야기의 초점이 왕에게서 하나님께 옮겨간다. 20절은 하나님이 산파들에게 은혜를 베푸셨다고 전하면서, 곧바로 백성이 번성하고 매우 강성해졌다고 덧붙인다. 바로의 노역 정책에도 멈추지 않았던 번성이 영아 살해의 위협 속에서도 이어진다는 것이다. 여기서 출애굽기는 강대국의 정책이 민족의 미래를 완전히 결정한다는 왕의 계산과 다른 결과를 놓는다.","21절은 산파들이 하나님을 경외하였으므로 하나님이 그들에게 ‘집들’을 이루어 주셨다고 말한다. 히브리어 בָּתִּים(바팀, ‘집들’)은 건물 자체뿐 아니라 가정 또는 가문을 가리킬 수 있다. 번역주들은 ‘가족/가정’을 가능한 의미로 제시한다. 따라서 이를 산파들이 부자가 되어 큰 집을 얻었다는 뜻으로 제한해서는 안 된다. 아이들의 생명을 지킨 이들에게 하나님이 가정과 미래를 허락하셨다는 이해가 자연스럽지만, 구체적인 가족 구성이나 자녀 수는 제시되지 않는다.","이 단락은 하나님의 응답을 마법 같은 즉각적 해결로 그리지 않는다. 산파들에게 선을 베푸시고 백성이 번성하지만, 정치적 폭력은 끝나지 않기 때문이다. 바로 다음 절은 그 사실을 다시 확인시킨다."]},{"id":"exo1-22-22","v1":22,"v2":22,"title":"은밀한 살해에서 공개적 명령으로","paragraphs":["산파들의 거부로 통제에 실패한 바로는 명령의 대상을 바꾼다. 이제 특정 산파들에게 은밀하게 남자아이를 죽이라고 지시하는 것이 아니라 ‘모든 자기 백성’에게 태어난 남자아이를 강에 던지고 여자아이는 살려 두라고 명령한다. 폭력이 몇 사람의 손에 맡겨진 비밀 정책에서 사회 전체에 요구되는 공개적 명령으로 확대된 것이다. unfoldingWord 자료는 22절의 ‘너희’가 여러 사람에게 주어진 명령이며 왕의 백성을 향한다고 설명한다.","나일 강은 애굽 사회에 물과 생계를 공급하는 중심 수계다. 그러나 이 명령 속에서 그 강은 생명을 받쳐 주는 장소가 아니라 아이들을 죽이는 수단으로 전락한다. 본문이 말하는 것은 강의 지리적 좌표가 아니라, 제국이 일상의 환경마저 생명을 파괴하는 데 동원하려 했다는 잔혹한 반전이다.","마지막 절은 문제를 해결하지 않고 열린 위협으로 끝난다. 그래서 출애굽기 2장에서 한 어머니가 아기를 숨기고, 마침내 물 위에 갈대 상자를 띄우는 이야기가 절박하게 읽힌다. 강에 던져 죽이라는 명령을 뒤이어, 바로 그 강에서 한 아이의 생명이 보존되는 이야기가 시작된다. 본문 간의 이 연결은 출애굽기의 서사 설계에서 특히 중요한 부분이다."]}],"lexicalCards":[],"discoveries":[{"id":"exo1-15-16-disc","title":"이름 없는 왕, 이름이 남은 산파들","paragraphs":["앞 단락에서 바로는 이스라엘의 번성을 국가적 위협으로 규정하고 고된 노동을 부과했다(1:8–14). 그러나 12절은 그들이 학대를 받을수록 더 많아졌다고 말한다. 15절에 이르면 탄압의 대상이 노동하는 어른들에서 이제 막 세상에 태어나는 아이들로 옮겨간다. 권력은 사람의 현재 노동을 통제하는 데서 그치지 않고, 그 민족의 미래 자체를 없애려 한다.","화자는 애굽 왕의 개인 이름을 알려 주지 않는다. 반대로 히브리 산파 두 사람의 이름은 또렷하게 적는다. 십브라와 부아다. 당대의 사회적 지위와 힘을 기준으로 보면 왕과 산파는 비교하기 어려웠을 것이다. 그러나 이야기의 중심은 군사력이나 궁정의 위엄이 아니라, 왕의 뜻을 거슬러 생명을 보전한 두 사람에게로 옮겨간다. 이 이름의 대비는 본문이 펼치는 문학적 역전이다. 권력자는 이름 없이 남고, 생명을 지킨 사람들은 이름으로 기억된다.","두 이름이 나왔다고 해서 이스라엘 전체에 산파가 오직 둘뿐이었다고 단정할 수는 없다. Tyndale Open Study Notes는 두 사람이 더 큰 산파 집단을 대표했을 가능성을 제시한다. 하지만 이것은 가능한 역사적 설명이지, 본문이 직접 밝힌 조직 체계는 아니다. 여기서 확실한 것은 왕이 십브라와 부아에게 살해 명령을 내렸고, 화자가 그들의 이름을 보존했다는 사실이다.","왕의 명령은 남아라면 죽이고 여아라면 살려 두라는 것이었다. 16절의 히브리어 표현 ‘두 돌 위를 보다’(עַל־הָאָבְנָיִם)는 출산 과정의 특정 기구 또는 출산 상황을 가리키는 난해한 표현이다. 흔히 출산 의자 또는 출산대로 설명하지만 물건의 정확한 형태를 확정할 수는 없다. 이 표현의 핵심은 왕이 산파들이 출산 현장에 가장 가까이 있다는 점을 살인에 이용하려 했다는 것이다. 생명을 돕는 손을 죽음의 도구로 바꾸려 한 셈이다."]},{"id":"exo1-17-18-disc","title":"두려움의 질서가 뒤집히다","paragraphs":["17절의 첫 전환은 짧지만 강하다. ‘그러나 산파들은 하나님을 두려워하여’라는 진술이 왕의 명령과 정면으로 맞선다. 이 대목에서 ‘두려워하다’는 동사 ירא(야레)의 의미는 공포에 질렸다는 데 있지 않다. 누구의 권위를 궁극적으로 인정하는가 하는 경외의 문제다. 왕에게 항명하면 생명이 위험해질 수 있는 상황에서 산파들은 보이지 않는 하나님의 뜻을 더 무겁게 받아들인다.","서술은 그들의 내면을 길게 상상하지 않는다. 다만 명령과 행동의 대조를 분명히 제시한다. 왕은 남자아이들을 죽이라 했지만 산파들은 그들을 살렸다. 여기에는 ‘하지 않았다’는 소극적 거부뿐 아니라 아이들의 생명을 보전했다는 적극적인 결과가 담겨 있다. 인간의 명령이 하나님의 생명 보전 뜻과 충돌할 때 두 사람은 행동으로 경계선을 그었다.","바로는 즉시 그들을 불러 묻는다. ‘어찌하여 이같이 하여 남자아이들을 살렸느냐?’ 왕의 질문 자체가 그 명령이 실패했음을 드러낸다. 대제국의 최고 권력자가 가장 약해 보이는 여성들에게 실패의 이유를 묻는 장면은 출애굽기의 권력 역전을 한층 또렷하게 보여 준다."]},{"id":"exo1-19-19-disc","title":"산파들의 대답과 서술자의 침묵","paragraphs":["산파들은 히브리 여자들이 애굽 여자들과 달리 ‘생기가 있어서’ 산파가 오기 전에 아이를 낳는다고 대답한다. 이 대답을 읽을 때에는 두 가지를 구분해야 한다. 첫째, 산파들이 실제로 이렇게 말했다는 것은 본문의 진술이다. 둘째, 그 설명이 모든 출산 상황에 대한 정확한 보고였는지, 왕을 속이기 위한 답변이었는지는 본문이 직접 판정하지 않는다.","Tyndale 주석은 산파들이 자신의 참된 동기를 바로에게 모두 말하지 않았을 가능성을 적극적으로 논한다. 반면 unfoldingWord의 번역주는 이 대답의 논리, 곧 히브리 여인들이 활력이 있어서 산파가 도착하기 전에 출산한다는 진술이 어떻게 연결되는지를 설명한다. 따라서 독자에게는 산파의 대답을 미화하여 무조건적 거짓말의 모범으로 만들거나, 반대로 구체적인 출산 속도를 역사적 사실로 확정하지 않는 태도가 필요하다.","핵심은 본문이 그들을 칭찬하는 이유다. 서술자는 그들이 말을 교묘하게 잘했기 때문이라고 말하지 않는다. 반복하여 강조하는 이유는 ‘하나님을 경외했기 때문’이다(17, 21절). 본문은 그들의 모든 표현에 대한 일반적 윤리 규칙을 제시하기보다, 생명을 파괴하라는 명령 앞에서 하나님을 경외한 행동을 조명한다."]},{"id":"exo1-20-21-disc","title":"하나님이 좋게 여기신 것과 계속되는 번성","paragraphs":["이제 이야기의 초점이 왕에게서 하나님께 옮겨간다. 20절은 하나님이 산파들에게 은혜를 베푸셨다고 전하면서, 곧바로 백성이 번성하고 매우 강성해졌다고 덧붙인다. 바로의 노역 정책에도 멈추지 않았던 번성이 영아 살해의 위협 속에서도 이어진다는 것이다. 여기서 출애굽기는 강대국의 정책이 민족의 미래를 완전히 결정한다는 왕의 계산과 다른 결과를 놓는다.","21절은 산파들이 하나님을 경외하였으므로 하나님이 그들에게 ‘집들’을 이루어 주셨다고 말한다. 히브리어 בָּתִּים(바팀, ‘집들’)은 건물 자체뿐 아니라 가정 또는 가문을 가리킬 수 있다. 번역주들은 ‘가족/가정’을 가능한 의미로 제시한다. 따라서 이를 산파들이 부자가 되어 큰 집을 얻었다는 뜻으로 제한해서는 안 된다. 아이들의 생명을 지킨 이들에게 하나님이 가정과 미래를 허락하셨다는 이해가 자연스럽지만, 구체적인 가족 구성이나 자녀 수는 제시되지 않는다.","이 단락은 하나님의 응답을 마법 같은 즉각적 해결로 그리지 않는다. 산파들에게 선을 베푸시고 백성이 번성하지만, 정치적 폭력은 끝나지 않기 때문이다. 바로 다음 절은 그 사실을 다시 확인시킨다."]},{"id":"exo1-22-22-disc","title":"은밀한 살해에서 공개적 명령으로","paragraphs":["산파들의 거부로 통제에 실패한 바로는 명령의 대상을 바꾼다. 이제 특정 산파들에게 은밀하게 남자아이를 죽이라고 지시하는 것이 아니라 ‘모든 자기 백성’에게 태어난 남자아이를 강에 던지고 여자아이는 살려 두라고 명령한다. 폭력이 몇 사람의 손에 맡겨진 비밀 정책에서 사회 전체에 요구되는 공개적 명령으로 확대된 것이다. unfoldingWord 자료는 22절의 ‘너희’가 여러 사람에게 주어진 명령이며 왕의 백성을 향한다고 설명한다.","나일 강은 애굽 사회에 물과 생계를 공급하는 중심 수계다. 그러나 이 명령 속에서 그 강은 생명을 받쳐 주는 장소가 아니라 아이들을 죽이는 수단으로 전락한다. 본문이 말하는 것은 강의 지리적 좌표가 아니라, 제국이 일상의 환경마저 생명을 파괴하는 데 동원하려 했다는 잔혹한 반전이다.","마지막 절은 문제를 해결하지 않고 열린 위협으로 끝난다. 그래서 출애굽기 2장에서 한 어머니가 아기를 숨기고, 마침내 물 위에 갈대 상자를 띄우는 이야기가 절박하게 읽힌다. 강에 던져 죽이라는 명령을 뒤이어, 바로 그 강에서 한 아이의 생명이 보존되는 이야기가 시작된다. 본문 간의 이 연결은 출애굽기의 서사 설계에서 특히 중요한 부분이다."]}],"canonicalLinks":[{"ref":"창세기 12:2; 17:2–6","note":"번성 약속과 출 1:7, 1:20의 연결"},{"ref":"출애굽기 2:1–10","note":"22절의 명령을 배경으로 읽히는 다음 단락"},{"ref":"출애굽기 2:23–25","note":"이스라엘의 부르짖음을 들으시는 하나님"}],"theologicalSynthesis":["동시에 성경은 두 사람의 저항이 곧장 폭력을 종식했다고 말하지 않는다. 오히려 정책은 더 넓은 명령으로 확대된다. 생명을 지키는 믿음의 행동과 아직 끝나지 않은 고통이 한 단락 안에 공존한다. 이 긴장은 다음 장의 모세 이야기, 더 멀리는 하나님이 이스라엘의 부르짖음을 들으시는 이야기(2:23–25)를 향해 독자를 이끈다."],"alternativeReadings":[{"title":"본문에서 열려 있는 문제들","paragraphs":["**‘히브리 산파’의 정체:** 산파들이 히브리 여성인지, 히브리 여성을 돕는 산파인지는 번역상 논의할 수 있다. 서술의 중심은 민족 분류의 확정보다 산파들의 행동에 있다.","**출산대의 두 돌(16절):** 히브리어 표현은 난해하다. 출산 의자라는 설명을 소개하되 물리적 형태를 확정하지 않는다.","**산파들의 설명(19절):** 대답의 역사적 정확성과 도덕적 성격은 논쟁 가능하다. 서술자가 명시적으로 칭찬한 근거는 하나님 경외와 생명 보호라는 점을 분리해 읽는다.","**‘집들’(21절):** 가정·가문으로 이해할 수 있으나 구체적인 경제적 번영이나 후손 수를 단정하지 않는다.","**정경적 연결:** 창세기의 번성 약속(창 12:2; 17:2–6)과 출 1:7, 1:20의 연결은 신학적·문학적 종합이다. 다음 단락인 출 2:1–10은 바로의 22절 명령을 배경으로 읽힌다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"StudyNotes.xml Exod.1.15-22","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"tn_EXO.tsv 1:15-22","license":"CC BY-SA 4.0"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_EXODUS_1_8_14_WORBS_CORE_20261011_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/13시대_인물사건_관계연구/JBC_EXODUS_1_8_14_WORBS_CORE_20261011_01.md","sourceSha256":"52dc4615c06ae881397f122de478c0e8f43baba7181831f9d2bfb42311db7d2d","passage":{"book":"exo","chapter":1,"v1":8,"v2":14,"ref":"출애굽기 1:8–14"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"PASS_WITH_VERIFY","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"왕이 잊은 이름, 지워지지 않는 약속","overview":["작은 가족으로 애굽에 들어왔던 이스라엘은 오랜 세월 동안 큰 백성이 되었다. 그러나 그들을 바라보는 애굽의 시선이 달라졌다. 요셉을 알지 못하는 왕이 등장하자, 번성은 축복이 아니라 두려운 위협으로 여겨졌고 그 두려움은 강제노동이라는 억압으로 바뀌었다. 그런데 왕의 계산과 달리 이스라엘은 더욱 번성했다. 출애굽기는 이 역설을 통해, 인간의 권력이 하나님의 오래된 약속과 부딪히는 순간을 보여 준다."],"centralMessage":"요셉을 알지 못하는 왕은 이스라엘의 번성을 두려워하여 강제노동으로 억압하지만, 백성은 오히려 더욱 번성한다. 왕의 두려움과 통제는 조상들에게 주어진 약속을 끝내지 못한다.","literaryStructure":[{"v1":8,"v2":8,"title":"요셉을 알지 못하는 왕이 등장하다"},{"v1":9,"v2":10,"title":"왕은 왜 이스라엘을 두려워했을까?"},{"v1":11,"v2":12,"title":"억누를수록 더욱 번성하다"},{"v1":13,"v2":14,"title":"사람들의 삶이 쓰게 되다"}],"sections":[{"id":"exo1-8-8","v1":8,"v2":8,"title":"요셉을 알지 못하는 왕이 등장하다","paragraphs":["방금 전까지 출애굽기는 생명의 언어로 가득했다. 야곱의 가족은 생육하고 번성했으며, 땅에 가득할 만큼 많아졌다. 창세기의 약속이 세대를 넘어 조용히 자라나는 듯했다. 그런데 그 밝은 문장 다음에 분위기를 바꾸는 한 사람이 나타난다. 요셉을 알지 못하는 새로운 왕이다.","요셉이라는 이름은 애굽의 역사에서 결코 가볍지 않았다. 큰 흉년이 닥쳤을 때 그는 곡식을 준비하고 관리하여 수많은 사람의 생명을 지켰다. 야곱의 가족이 굶주림을 피해 애굽으로 내려왔을 때에도 요셉은 그들이 머물 길을 열어 주었다. 한 가족이 애굽에 들어올 때 요셉이라는 이름은 보호와 생존을 연결해 주는 이름이었다.","그러나 새로운 왕에게 그 이름은 아무런 의미가 없었다. 히브리어 본문은 그가 요셉을 ‘알지 못했다’고 말한다. 그가 요셉에 대해 실제로 들어본 적이 없었는지까지 알려 주지는 않는다. 중요한 것은 이제 왕이 요셉의 공적이나 그 가족과의 오랜 관계를 고려하지 않는다는 사실이다. 어제까지 환대의 이유였던 과거가 오늘은 아무런 보호가 되지 못한다.","사람들의 기억에서는 요셉의 이름이 희미해질 수 있다. 하지만 출애굽기의 이야기 자체는 그의 이름을 잊지 않는다. 오히려 바로 앞에서 이스라엘이 얼마나 풍성히 자랐는지를 먼저 이야기한 뒤, 그 번성을 낯설고 두려운 눈으로 바라보는 왕을 등장시킨다. 이제 같은 백성을 향한 두 시선이 서로 맞서기 시작한다."]},{"id":"exo1-9-10","v1":9,"v2":10,"title":"왕은 왜 이스라엘을 두려워했을까?","paragraphs":["왕은 자기 사람들에게 이스라엘 자손이 자신들보다 많고 강하다고 말한다. 이 말은 왕이 백성을 어떻게 보고 있는지를 드러낸다. 그는 이스라엘의 가정과 일상, 오랫동안 애굽에서 살아온 역사를 보지 않는다. 먼저 숫자를 세고, 힘을 비교하며, 언젠가 닥칠지 모르는 위험을 상상한다.","그가 걱정하는 일들은 아직 일어나지 않았다. 전쟁이 터지면 이스라엘이 적의 편에 설지 모른다. 그들이 애굽과 싸울지도 모른다. 마침내 나라를 떠날지도 모른다. 그러나 왕은 이렇게 아직 현실이 되지 않은 일들을 하나의 확실한 위기처럼 묶는다. 불안은 다른 사람을 의심할 이유가 되고, 의심은 그들을 통제할 정책의 근거가 된다.","그는 ‘우리가 그들을 지혜롭게 다루자’고 제안한다. 원어의 표현, 니트하크마(נִתְחַכְּמָה)는 ‘우리가 교묘하게 대처하자’는 뉘앙스를 품고 있다. 이 말 자체만 들으면 능숙한 정치적 판단처럼 보일 수 있다. 하지만 그가 곧 시행하는 정책은 사람들을 괴롭혀 힘을 꺾는 것이다. 자신이 선택한 방법을 지혜라고 부르는 사람과, 그 방법 때문에 고통을 당할 사람 사이에는 커다란 거리가 있다.","여기에는 묘한 모순도 있다. 왕은 이스라엘이 너무 강해져서 떠날까 두려워한다. 하지만 그들이 떠나지 못하도록 택한 방법은 고통스러운 노동으로 그들을 묶어 두는 것이다. 그는 이스라엘을 불안한 이웃으로 바라보면서도, 동시에 놓치고 싶지 않은 노동력으로 대한다. 그렇게 두려움은 점차 다른 사람의 삶을 통제할 권력으로 변한다."]},{"id":"exo1-11-12","v1":11,"v2":12,"title":"억누를수록 더욱 번성하다","paragraphs":["왕의 계획은 말로 끝나지 않았다. 애굽은 이스라엘 위에 강제노동을 감독하는 관리들을 세웠다. 사람들에게 무거운 짐을 지우고 일을 시켜, 고되게 만들고 힘을 소진시키려 했다. 이스라엘은 바로를 위한 비돔과 라암셋이라는 저장 도시를 짓는 데 동원되었다. 왕의 걱정이 이제는 사람들의 하루를 지배하는 노동 제도가 된 것이다.","왕이 원하는 결과는 분명했다. 노동이 무거워질수록 이스라엘의 기세가 꺾이고, 번성도 멈춰야 했다. 하지만 12절은 뜻밖의 이야기로 이어진다. 애굽이 이스라엘을 더 괴롭힐수록 이스라엘은 더 많아지고 더욱 퍼져 나갔다.","히브리어 문장은 이 반전을 귀에 들리도록 표현한다. ‘그들이 괴롭힐수록, 그만큼 더욱 많아지고, 그만큼 더욱 뻗어 나갔다.’ 특히 왕이 10절에서 두려워한 것이 ‘그들이 더 늘어나는 것’이었는데, 12절은 바로 그 ‘늘어나다’라는 동사를 다시 사용한다. 왕이 막으려던 일이 멈추지 않았다는 사실을 같은 말로 들려주는 것이다.","이 장면을 앞선 창세기와 함께 읽으면 더욱 깊은 의미가 보인다. 하나님은 아브라함의 후손을 많게 하시겠다고 약속하셨고, 야곱에게는 애굽에서 큰 민족을 이루게 하시겠다고 말씀하셨다. 왕은 그 백성을 약하게 만들려 했지만 이야기의 흐름은 조상들에게 주신 약속 쪽으로 움직이고 있었다.","그렇다고 이스라엘이 겪은 고통이 작았다는 뜻은 아니다. 백성이 번성했다는 사실과 그들의 삶이 혹독했다는 사실은 동시에 참이다. 억압이 좋은 일을 만들어 낸다고 말하는 것이 아니라, 잔혹한 권력조차 하나님의 약속이 이어지는 이야기를 끝내지 못했다는 것이다. 바로 이것이 왕의 계획이 실패하는 자리에 놓인 출애굽기의 깊은 역설이다."]},{"id":"exo1-13-14","v1":13,"v2":14,"title":"사람들의 삶이 쓰게 되다","paragraphs":["계획이 뜻대로 되지 않자 애굽의 대응은 더 거칠어졌다. 본문은 이스라엘에게 강제로 일을 시켰다고 말하면서 ‘가혹하게’라는 표현을 거듭 사용한다. 같은 말을 반복하는 것은 그들이 얼마나 혹독한 생활을 해야 했는지 독자에게 똑똑히 들려주기 위해서다.","이어지는 말은 더욱 아프다. 애굽 사람들이 이스라엘 자손의 ‘삶을 쓰게 만들었다’는 것이다. 삶이 쓰다는 말은 우리가 겪는 고통을 유난히 생생하게 전한다. 단순히 일이 많았다거나 생활이 힘들었다는 말보다 깊다. 쉬어야 할 시간도, 하루를 기쁘게 보낼 여유도, 내일을 기대할 마음도 무거운 노동 속에 짓눌려 가는 모습을 떠올리게 한다.","본문은 그 노동을 구체적으로 들려준다. 진흙을 준비하고 벽돌을 만들며, 들에서는 여러 가지 고된 일을 했다. 이집트의 건축 현장에서 햇볕에 말린 흙벽돌은 흔한 재료였고, 이것을 만드는 일에는 많은 사람의 손과 시간이 필요했다. 출애굽기 5장에서 모세와 바로가 마주할 때도 벽돌과 짚을 둘러싼 갈등이 다시 등장한다. 그러므로 여기의 노동 묘사는 뒤따를 구원 이야기와 따로 떨어진 배경 설명이 아니다. 이스라엘이 왜 해방을 필요로 했는지, 그 삶의 무게를 미리 보여 주는 장면이다.","이렇게 8–14절은 한 왕의 등장으로 시작하여 평범한 사람들의 쓰라린 일상으로 끝난다. 처음에는 왕이 무엇을 두려워하는지를 들려주지만 마지막에는 그 두려움 때문에 누가 고통받는지를 보게 한다. 왕은 번성을 멈추려 했으나 번성은 멈추지 않았다. 대신 그의 억압은 더욱 심해졌다. 바로 그 자리에서 출애굽이라는 하나님의 구원 이야기가 왜 필요한지가 선명해진다."]}],"discoveries":[{"id":"exo8-lang-0","domain":"original_language","title":"8 · יָדַע yādaʿ","paragraphs":["Qal 완료 3남단, לֹא 부정과 함께 '알지 못했다'; 서사적으로 요셉의 공적을 인정하지 않는 정치적 단절"]},{"id":"exo8-lang-1","domain":"original_language","title":"9 · רַב rav; עָצוּם ʿāṣûm","paragraphs":["많고 강함; 바로의 연설 속 집단 평가이지 확정 인구 통계 아님"]},{"id":"exo8-lang-2","domain":"original_language","title":"10 · חָכַם ḥākam → נִתְחַכְּמָה nitḥakkəmāh","paragraphs":["히트파엘 청유형 1공복: '우리가 교묘히 다루자'"]},{"id":"exo8-lang-3","domain":"original_language","title":"11 · מַס mas → מִסִּים missîm","paragraphs":["부역·강제노동 편제, שָׂרֵי 미스임은 감독 관리"]},{"id":"exo8-lang-4","domain":"original_language","title":"11 · עָנָה ʿānāh → עַנֹּתוֹ ʿannōtô","paragraphs":["Piel 부정사 연결형 + 3남단 목적어: '그들을 압제하려고'"]},{"id":"exo8-lang-5","domain":"original_language","title":"12 · רָבָה rābāh → יִרְבֶּה yirbeh; פָּרַץ pāraṣ → יִפְרֹץ yiprōṣ","paragraphs":["각각 Qal 미완료 3남단, 집합명사 백성의 증가와 확산"]},{"id":"exo8-lang-6","domain":"original_language","title":"12 · קוּץ qûṣ → וַיָּקֻצוּ wayyāquṣû","paragraphs":["Qal 연속형 3남복: 두려움·혐오"]},{"id":"exo8-lang-7","domain":"original_language","title":"13–14 · פֶּרֶךְ perek","paragraphs":["가혹·강압의 명사, 두 절에서 반복"]},{"id":"exo8-lang-8","domain":"original_language","title":"14 · מָרַר mārar → וַיְמָרְרוּ wayəmarərû","paragraphs":["Piel 연속형 3남복: '그들의 삶을 쓰게 만들다'"]}],"lexicalCards":[],"canonicalLinks":[{"ref":"창세기 12:2; 15:5; 46:3","note":"창세기 12:2; 15:5; 46:3 — 약속의 지속: — 아브라함과 야곱에게 약속된 큰 민족의 형성이 애굽에서 진행된다는 점이 1:7·12를 함께 설명한다. 1:12의 반전은 그 약속을 배경에 두어 읽을 때 강해진다."},{"ref":"창세기 15:13–14","note":"창세기 15:13–14 — 압제와 구원의 예고: — 낯선 땅에서의 종살이와 괴롭힘이 이미 아브라함에게 예고되었다는 서사적 연결이다. 이를 특정 왕조나 절대연대 확정의 근거로 전용하지 않는다."},{"ref":"출애굽기 2:23–25; 3:7–10","note":"출애굽기 2:23–25; 3:7–10 — 고통이 하나님의 귀에 이르다: — 지금은 이스라엘의 고통이 전경에 있고, 이후 하나님이 그 고통을 보시고 들으시며 구원 행위를 시작하신다."},{"ref":"출애굽기 5:6–18; 6:6","note":"출애굽기 5:6–18; 6:6 — 벽돌 노동과 구원의 약속: — 1장에 제시된 노동 착취는 모세와 바로가 충돌하는 현장에서 다시 구체화되고, 하나님은 무거운 짐 아래에서 이스라엘을 꺼내시겠다고 선언하신다."},{"ref":"시편 105:24–25","note":"시편 105:24–25 — 후대의 신학적 회고: — 하나님이 백성을 번성하게 하셨고 대적들의 마음이 바뀌어 미워하게 되었다는 시편의 해석은 창세기 약속과 출애굽기의 갈등을 함께 재구성한다."},{"ref":"신명기 26:6–8","note":"신명기 26:6–8 — 후대 공동체의 역사 기억: — 애굽의 학대와 여호와의 구원을 신앙 공동체가 다시 고백하도록 만드는 기억의 본문."}],"theologicalSynthesis":["앞선 1:1–7과 이 단락은 한 쌍처럼 읽힌다. 작은 가족이 큰 백성이 되었다는 서론 다음에, 그 큰 백성을 두려워하는 왕의 이야기가 따라온다. 독자가 하나님의 약속의 관점에서 보던 번성을 바로는 제어해야 할 위험으로 해석한다. 같은 ‘많아짐’을 둘러싼 두 시선의 차이가 이후 출애굽의 갈등을 이끈다.","여기에는 창세기 15장의 기억도 흐른다. 하나님은 아브라함에게 그 후손이 낯선 땅에서 종이 되어 괴롭힘을 당할 때가 올 것이라고 말씀하셨다. 이제 출애굽기는 그 고통을 구체적인 사람과 노동의 이야기로 보여 준다. 그리고 다음 장들에서 하나님은 백성의 신음을 들으시고 그들의 고통을 보셨다고 말씀하신다(출 2:23–25; 3:7). 그러므로 1:8–14는 구원 이야기의 어두운 배경만이 아니다. 앞으로 하나님이 누구의 울음에 응답하시는지를 독자가 알도록 하는 본문이다.","본문은 새 왕의 이름이나 정확한 왕조를 알려 주지 않는다. 몇몇 주석은 당시 이집트의 정치적 변화와 힉소스의 축출을 연결하여 설명하지만, 그 가능성이 곧 성경 본문의 확정된 역사 정보가 되는 것은 아니다. 이 단락에서 가장 분명한 것은 왕의 이름보다 그가 행한 일이며, 추정된 연대보다 억압받는 사람들의 삶이다.","이야기는 여기서 끝나지 않는다. 다음 단락에서는 왕의 억압이 갓 태어난 남자아이들의 생명까지 겨냥하고, 산파 십브라와 부아가 그 폭력 앞에 서게 된다(출 1:15–22). 인간의 권력이 살아 있는 사람을 숫자와 노동력으로 다루기 시작한 자리에, 생명을 지키려는 새로운 장면이 열린다."],"relatedResearch":[],"alternativeReadings":[],"cautions":[],"readerProse":{"kind":"PRESENTATION_ONLY_DERIVATIVE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/EXODUS_01_08_14_READABLE_WORBS_v0.1_CANDIDATE.md","sha256":"a716589526ed0da7c131f8d22c7a946341e757c28336d82eda1834410a1a97d8","professionalMeaningSourceId":"JBC_EXODUS_1_8_14_WORBS_CORE_20261011_01","professionalMeaningSourceSha256":"52dc4615c06ae881397f122de478c0e8f43baba7181831f9d2bfb42311db7d2d","editorialStatus":"CLAIM_PARITY_REVIEWED_NO_NEW_PROFESSIONAL_APPROVAL"},"readerSources":[{"name":"Tyndale Open Study Notes","edition":"2022","locators":["Exod.1.1-22","Exod.1.8-10","Exod.1.10","Exod.1.11","Exod.1.12","Exod.1.14"],"license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"tn_EXO.tsv 1:8-14","license":"CC BY-SA 4.0"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_EXODUS_1_1_7_WORBS_CORE_20261011_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/13시대_인물사건_관계연구/JBC_EXODUS_1_1_7_WORBS_CORE_20261011_01.md","sourceSha256":"f357d8e57d272a791a9f85d6860ffdf605048ebec903913d581789b278ac4c4a","passage":{"book":"exo","chapter":1,"v1":1,"v2":7,"ref":"출애굽기 1:1–7"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"PASS_WITH_VERIFY","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"이름을 다시 부르는 책, 약속이 자라는 땅","overview":["출애굽기는 영웅의 등장이나 압제의 참상으로 시작하지 않는다. 먼저 오래전에 애굽으로 들어간 사람들의 이름을 다시 부른다. 한 세대가 사라진 뒤에도 그 가족이 큰 백성으로 자라난 이야기를 들려주며, 창세기에서 주어진 약속이 새로운 역사 속으로 이어지고 있음을 보여 준다."],"centralMessage":"출애굽기 1:1–7은 조상의 세대가 사라진 뒤에도 야곱의 집안이 애굽에서 큰 공동체로 번성하였음을 보여 주며, 창세기의 생육과 조상들에게 주어진 약속이 출애굽의 새 역사 속으로 이어지고 있음을 증언한다.","literaryStructure":[{"v1":1,"v2":4,"title":"출애굽기는 왜 사람들의 이름으로 시작할까?"},{"v1":5,"v2":5,"title":"칠십 명이라는 숫자가 들려주는 이야기"},{"v1":6,"v2":6,"title":"요셉의 죽음 뒤에도 이야기는 끝나지 않는다"},{"v1":7,"v2":7,"title":"‘많아졌다’는 한마디로 끝내지 않은 이유"}],"sections":[{"id":"exo-1-1-4","v1":1,"v2":4,"title":"출애굽기는 왜 사람들의 이름으로 시작할까?","paragraphs":["우리는 출애굽기를 생각할 때 갈대상자에 담긴 모세, 바로의 궁전, 열 가지 재앙, 갈라지는 바다를 먼저 떠올린다. 그러나 책은 이 거대한 장면들보다 먼저 르우벤과 시므온, 레위와 유다를 비롯한 야곱의 아들들을 불러 낸다. 한 나라의 탄생을 이야기하면서 그 출발점이었던 평범한 가족의 이름을 잊지 않는 것이다.","히브리어 첫머리는 ‘그리고 이것들은 이름들이다’에 해당하는 표현으로 시작한다. 셰모트(שְׁמוֹת), 곧 ‘이름들’은 출애굽기의 히브리어 명칭이기도 하다. 창세기 46:8에서도 애굽으로 내려가는 이스라엘 가족의 명단을 소개할 때 비슷한 표현이 나온다. 두 책 사이에 세월은 흘렀지만 이야기의 실은 끊어지지 않았다. 출애굽기는 창세기의 마지막 장면을 이어받아 그 가족이 어떻게 하나의 백성이 되었는지를 들려준다.","이름 목록에는 요셉이 빠져 있다. 그를 잊었기 때문이 아니다. 5절이 곧바로 요셉은 이미 애굽에 있었다고 알려 준다. 흉년을 피해 내려온 야곱의 식구들과 먼저 그곳에 있었던 요셉, 두 줄기의 이야기가 한 가족의 역사 안에서 만난다. 이 명단은 숫자 이전에, 조상들의 삶 속에서 시작된 약속의 역사를 기억하게 한다."]},{"id":"exo-1-5-5","v1":5,"v2":5,"title":"칠십 명이라는 숫자가 들려주는 이야기","paragraphs":["애굽으로 들어온 야곱의 후손은 ‘칠십 명’이었다. 이 숫자를 오늘날의 주민등록 통계처럼 읽을 필요는 없다. 본문은 집안의 모든 종과 동행자를 빠짐없이 셌다고 설명하지 않는다. ‘야곱의 허리에서 나온 사람’이라는 히브리어 표현은 그의 후손을 가리키는 혈통의 은유이며, ‘네페쉬(נֶפֶשׁ)’는 이 문맥에서 추상적인 영혼이 아니라 사람을 세는 말로 쓰인다.","여기에는 작은 본문비평의 창문도 있다. 히브리어 마소라 본문은 칠십 명이라고 기록하지만, 그리스어 칠십인역 계열과 사도행전 7:14에는 칠십오 명이라는 전승이 나타난다. 어느 쪽이든 이 서론을 읽는 데 필요한 중심은 달라지지 않는다. 한때 애굽에 내려온 이들은 작은 친족 공동체였고, 앞으로 등장할 이스라엘 백성은 바로 그 가족에게서 시작되었다. 숫자의 차이를 성급히 하나의 산술 계산으로 봉합하기보다, 본문 전승의 차이는 차이대로 남겨 두는 편이 낫다.","이 작은 가족의 규모는 7절과 만날 때 새로운 무게를 얻는다. 출애굽기는 처음부터 큰 민족이 애굽에 들어왔다고 말하지 않는다. 작게 시작한 가족이 시간이 지나 큰 백성으로 자라났다는 사실을 보여 주기 위해 먼저 칠십 명을 기억한다."]},{"id":"exo-1-6-6","v1":6,"v2":6,"title":"요셉의 죽음 뒤에도 이야기는 끝나지 않는다","paragraphs":["“요셉과 그의 모든 형제와 그 시대 사람은 다 죽었고.” 문장은 짧지만 그 안에는 긴 세월이 들어 있다. 창세기 끝에서 요셉의 죽음을 읽었던 독자는, 이제 그 형제들과 함께 살았던 한 세대 전체가 지나갔다는 소식을 듣는다. 자신들을 애굽으로 이끈 사람도, 그와 같은 시대를 살았던 이들도 더 이상 남아 있지 않다.","요셉은 식량을 마련하여 굶주림 속의 가족을 살렸다. 그러나 이스라엘의 미래가 요셉 한 사람의 수명에 매달려 있지는 않았다. 본문은 그가 죽었다는 사실을 충분히 말하면서도 이야기를 거기서 멈추지 않는다. 한 세대의 소멸을 전한 다음, 바로 다음 절에서 새로운 세대의 번성을 들려준다. 죽음과 생명의 연속성이 나란히 놓이면서 인간 지도자의 시대보다 더 긴 약속의 역사가 드러난다.","여기서 하나님은 직접 말씀하지 않으신다. 출애굽기 1:1–7은 당장의 해방을 선언하는 장면도 아니다. 그러나 창세기 46:3에서 야곱에게 애굽에서 큰 민족을 이루게 하시겠다고 하신 약속을 기억하면, 조용히 진행된 인구의 번성은 단순한 배경 설명 이상의 의미를 띤다. 하나님의 이름이 이 단락에서 직접 들리지 않는다는 사실과 약속의 흐름을 읽을 수 있다는 사실은 서로 모순되지 않는다. 후자는 앞선 성경 이야기와 함께 읽을 때 드러나는 신학적 해석이다."]},{"id":"exo-1-7-7","v1":7,"v2":7,"title":"‘많아졌다’는 한마디로 끝내지 않은 이유","paragraphs":["7절은 이스라엘 자손이 크게 늘었다는 사실을 놀라울 만큼 풍성한 언어로 말한다. 생육하고, 불어나고, 번성하고, 매우 강대해지고, 마침내 그 땅이 그들로 가득 찼다. 비슷한 뜻의 동사들을 잇달아 놓은 것은 문장을 길게 꾸미기 위해서가 아니다. 작은 가족이 큰 백성이 된 변화를 독자의 귀에 거듭 울리게 한다.","특히 ‘생육하다’에 해당하는 파루(פָּרוּ)는 창세기 1:28의 생육과 번성이라는 창조의 언어를 떠올리게 한다. ‘무리를 이루다’에 해당하는 바이쉬레추(וַיִּשְׁרְצוּ) 역시 창세기에서 생명이 풍성하게 퍼져 나갈 때 쓰이는 어휘와 연결된다. 하나님이 창조 세계에 주신 생명의 충만함이 이제 이스라엘의 역사 안에서 다시 울리는 것이다. 창세기 46:3의 ‘큰 민족’이라는 약속을 떠올리면 이 울림은 더욱 뚜렷해진다.","그렇다고 7절이 애굽의 정확한 인구수나 거주 지도를 알려 주는 것은 아니다. ‘그 땅이 그들로 가득했다’는 표현은 번성의 규모를 힘 있게 묘사한다. 또한 이 번성이 곧바로 안전하고 평화로운 미래를 보장한다는 뜻도 아니다. 바로 다음 절에는 요셉을 알지 못하는 새로운 왕이 등장한다. 같은 번성을 하나님의 약속과 생명의 관점에서 바라보는 이야기와, 국가 권력의 위협이라는 관점에서 바라보는 이야기가 곧 충돌한다.","그렇기에 7절은 단순한 성공 보고서가 아니다. 앞으로 억압받을 백성이 이미 생명과 번성의 약속 안에서 자라나고 있었다는 사실을 먼저 보여 주는 문학적 전환점이다. 출애굽의 구원 사건을 이해하려면 하나님이 누구를 구원하시는지, 그리고 그들이 어떻게 그곳까지 이르게 되었는지를 먼저 알아야 한다."]}],"discoveries":[{"id":"exo1-lang-1","domain":"original_language","title":"שְׁמוֹת (셰모트, shemôt)","paragraphs":["명사 שֵׁם(셈, '이름')의 복수형이다. 출애굽기의 히브리어 책 이름도 첫머리의 이 단어에서 유래한다. 사람들의 '이름'을 다시 불러내는 서두는 창 46장의 가족 기억을 보존하는 문학적 장치이다."]},{"id":"exo1-lang-2","domain":"original_language","title":"הַבָּאִים (하바임, habbaʾîm)","paragraphs":["동사 בּוֹא(보, '오다·들어가다')의 관사 붙은 칼 능동분사 남성 복수형으로, '들어온 이들'을 가리킨다. 문맥은 야곱의 가족이 애굽에 도착한 과거 사건의 회고이지 매일 계속되는 이주라는 주장이 아니다."]},{"id":"exo1-lang-3","domain":"original_language","title":"נֶפֶשׁ (네페쉬, nefeš)","paragraphs":["'생명·사람·인격적 존재' 등의 의미 범위를 지닌다. 5절의 שִׁבְעִים נָפֶשׁ(쉬브임 네페쉬, '칠십 명')은 '영혼'의 비물질적 숫자를 세는 신학적 표현이 아니라 사람 수를 나타내는 관용 표현이다. '야곱의 허리에서 나온' יֹצְאֵי יֶרֶךְ־יַעֲקֹב(요츠에 예레크 야아코브)는 혈통을 나타내는 은유이다."]},{"id":"exo1-lang-4","domain":"original_language","title":"פָּרוּ (파루, pārû)","paragraphs":["원형 פָּרָה(파라, '열매 맺다·생육하다'), 칼 완료 3인칭 공통 복수이다. 창 1:28의 생육 명령, 창 47:27의 후손 번성과 연관된다."]},{"id":"exo1-lang-5","domain":"original_language","title":"וַיִּשְׁרְצוּ (바이쉬레추, wayyišrəṣû)","paragraphs":["원형 שָׁרַץ(샤라츠, '우글거리다·무리를 이루다'), 칼 서술형 연쇄 동사 3인칭 남성 복수이다. 창 1:20의 물속 생물들이 번성하는 어휘를 인간 공동체의 생명력에 비유적으로 적용한다. 이 표현을 인간을 동물로 낮추는 모욕으로 읽을 필요는 없다."]},{"id":"exo1-lang-6","domain":"original_language","title":"וַיִּרְבּוּ (바이르부, wayyirbû)","paragraphs":["원형 רָבָה(라바, '많아지다'), 칼 연쇄형으로 수적 증가를 강조한다. וַיַּעַצְמוּ (바야아츠무, wayyaʿaṣmû): 원형 עָצַם(아참, '강해지다·크게 되다')의 칼 연쇄형으로 세력과 규모가 커짐을 말한다. בִּמְאֹד מְאֹד (비메오드 메오드)는 강조 반복이다."]},{"id":"exo1-lang-7","domain":"original_language","title":"וַתִּמָּלֵא הָאָרֶץ אֹתָם (바팀말레 하아레츠 오탐)","paragraphs":["'땅이 그들로 가득 찼다'. מָלֵא(말레, '차다·채우다')의 니팔 연쇄형 3인칭 여성 단수와 주어 '땅'의 일치가 보인다. 여기서 הָאָרֶץ는 앞 문맥의 애굽 땅을 가리키는 것이 자연스럽지만, 정확히 고센만인지 이집트 전체인지 지리적 범위를 7절만으로 확정할 수는 없다."]},{"id":"exo1-textcrit-70-75","domain":"literary","title":"칠십 명과 칠십오 명","paragraphs":["칠십 명과 칠십오 명. 출 1:5의 마소라 본문과 창 46:27은 '70'이다. 칠십인역 계열 및 행 7:14에는 '75' 전승이 나타난다. 이 차이는 고대 전승의 집계·계보 범위 및 본문 전승의 차이를 반영하며, 이 단락 연구에서는 MT의 '70'을 본문으로 읽고 다른 전승을 각주성 VERIFY로 남긴다. 어느 한쪽이 필사 오류라고 단정하거나, 단일 산술식으로 모든 사본 차이를 해결했다고 주장하지 않는다. 사해문서의 개별 사본·본문판본은 이번 연구에서 직접 열람하지 않았으므로 독립 확증 대상으로 삼지 않는다."]}],"lexicalCards":[],"canonicalLinks":[{"ref":"창 46:8–27 → 출 1:1–5","note":"가족 이름과 숫자 — 야곱의 애굽 이주를 출애굽 서사의 출발점으로 재소환한다."},{"ref":"창 46:3; 47:27 → 출 1:7","note":"애굽에서 큰 민족·번성 — 조상에게 주신 약속의 방향이 이주 후 세대에서 가시화된다."},{"ref":"창 1:28; 9:1 → 출 1:7","note":"생육·번성·충만 — 창조 세계의 생명과 번성 어휘가 언약 백성의 서사에 다시 울린다. 직접적인 문장 동일성보다 어휘·주제적 반향이다."},{"ref":"창 50:26 → 출 1:6","note":"요셉의 죽음 — 한 인물의 생애를 끝맺은 창세기 결말이 출애굽기에서 세대 전체의 종결로 확장된다."},{"ref":"출 1:7 → 1:8–22","note":"번성과 압제의 긴장 — 축복의 징후를 바로의 국가 권력이 위협으로 읽으며 이야기의 갈등이 형성된다."},{"ref":"신 10:22; 행 7:17–18","note":"작은 수에서 큰 백성 — 후대 성경이 이스라엘의 번성을 구원 역사와 연결하여 회고한다. 행 7:14의 숫자 전승은 별도 구별한다."}],"theologicalSynthesis":["이 명제의 첫 절반은 본문 직접 관찰이며, 뒤 절반은 창 1:28·46:3·47:27과의 정경적 문맥 종합이다. 하나님이 이 단락에서 직접 발화하시거나 즉각적인 해방을 선언하셨다는 주장은 하지 않는다. 1:8 이후 압제는 번성의 소멸이 아니라 약속의 역사와 권력의 통제 사이에 발생하는 긴장이다.","이름·세대·번성의 세 단계가 이 짧은 서론의 문학적 흐름을 이룬다. 이름들은 창세기의 이야기를 출애굽기로 가져오고, 세대의 죽음은 지나간 시간을 압축하며, 번성의 언어는 창조와 조상들에게 주어진 약속을 새로운 역사에 연결한다. 칠십 명과 칠십오 명의 본문 전승, 애굽 안에서의 정확한 거주 범위와 기간은 이 문맥만으로 확정하지 않는다.","출애굽기의 첫 일곱 절은 아직 모세의 사명을 말하지 않는다. 바다도 갈라지지 않고, 바로의 압제도 본격적으로 시작되지 않았다. 하지만 독자가 먼저 보아야 할 장면은 이미 펼쳐졌다. 사람들의 이름을 기억하는 책에서, 한 세대가 지나가도 사라지지 않는 약속의 역사가 시작되고 있다."],"relatedResearch":[],"alternativeReadings":[],"cautions":[],"readerProse":{"kind":"PRESENTATION_ONLY_DERIVATIVE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/EXODUS_01_01_07_READABLE_WORBS_v0.1_CANDIDATE.md","sha256":"8d20841a045915f358e798b934259d8137edb039212b9b5fcae30799f6fa1788","professionalMeaningSourceId":"JBC_EXODUS_1_1_7_WORBS_CORE_20261011_01","professionalMeaningSourceSha256":"f357d8e57d272a791a9f85d6860ffdf605048ebec903913d581789b278ac4c4a","editorialStatus":"CLAIM_PARITY_REVIEWED_NO_NEW_PROFESSIONAL_APPROVAL"},"readerSources":[{"name":"Tyndale Open Study Notes","edition":"2022","locators":["Exod.1.1-22","Exod.1.1","Exod.1.2-4","Exod.1.5","Exod.1.6-7"],"license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"tn_EXO.tsv 1:1-7","license":"CC BY-SA 4.0"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_EXODUS_2_1_10_WORBS_READER_PILOT_20261011_01","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/EXODUS_02_01_10_READABLE_WORBS_v0.1_CANDIDATE.md","sourceSha256":"ee333b7f2a67cdf4d791ce9fc6ff5ba876ca8bf01e44c4c13a1b613234310d76","passage":{"book":"exo","chapter":2,"v1":1,"v2":10,"ref":"출애굽기 2:1–10"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"EDITORIAL_PASS_AUTHORITY_HOLD","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"죽음의 강에서 건져진 생명","overview":["바로는 히브리 남자아이를 나일강에 던지라고 명령했다(1:22). 그러나 그 강에서 한 아이가 죽지 않고 살아난다. 어머니는 아기를 숨기다가 갈대 상자에 눕혀 강가에 놓고, 누이는 멀찍이 서서 그 운명을 지켜본다. 뜻밖에도 아이를 발견해 불쌍히 여긴 사람은 바로의 딸이다. 아이는 친어머니의 품에서 자라다가 궁정으로 들어가 모세라는 이름을 얻는다. 죽음의 도구가 되도록 명령된 강이 도리어 구원의 길이 되는 역전 속에서, 출애굽기의 구원 이야기가 시작된다."],"centralMessage":"바로는 나일강을 생명을 없애는 도구로 삼으려 했다. 그러나 모세는 바로 그 강에서 건져진다. 압제의 명령 아래 위태로워진 생명이 평범한 사람들의 구체적인 행동과 예상 밖의 긍휼을 통해 지켜진 것이다. 하나님은 이 단락에서 직접 말씀하지 않으신다. 그럼에도 앞장에서 이어진 약속과 뒤에 펼쳐질 구원의 역사 속에서, 독자는 아직 드러나지 않은 하나님의 일하심을 바라보게 된다.\n\n어머니와 누이의 행동을 과장하여 모든 일을 처음부터 내다본 완벽한 계획으로 만들 필요도 없고, 공주의 긍휼을 단순한 우연으로 축소할 필요도 없다. 성경은 서로 다른 이들의 선택과 위험이 맞물리는 자리에서 한 생명이 보존되는 사건을 차분히 서술한다. 그 아이가 훗날 백성을 이끌 모세다.","literaryStructure":[{"v1":1,"v2":2,"title":"이름보다 먼저 드러난 생명"},{"v1":3,"v2":4,"title":"나일강에 놓인 작은 상자"},{"v1":5,"v2":6,"title":"바로의 집 안에서 시작된 반전"},{"v1":7,"v2":9,"title":"친어머니에게 돌아온 아이"},{"v1":10,"v2":10,"title":"물에서 건진 아이, 모세"}],"sections":[{"id":"exo2-1-2","v1":1,"v2":2,"title":"이름보다 먼저 드러난 생명","paragraphs":["이야기의 첫머리에는 아직 사람들의 이름이 등장하지 않는다. 레위 집안의 남자가 레위 집안의 여자와 혼인하고, 그 여자가 아들을 낳았다는 짧은 진술뿐이다. 출애굽기 6:20에 이르면 부모의 이름이 아므람과 요게벳으로 알려지지만, 이 장면의 화자는 이름을 앞세우지 않는다. 바로의 살해 명령 아래에서 한 아이를 낳아 지키려는 가족의 행동에 집중하도록 한다.","어머니는 아기가 '좋은' 것을 보고 석 달 동안 숨겼다. 히브리어 טוֹב(토브)는 '좋다', '아름답다', '훌륭하다'와 관련된 표현이다. 이를 어머니가 아이의 장래 위대함을 예언적으로 알아보았다는 뜻으로 단정할 수는 없다. 이야기의 직접적인 초점은 그녀가 아이를 소중히 여기고 그를 숨겼다는 데 있다. '좋다'는 표현은 창세기의 창조 서술과 어울리는 울림도 주지만, 여기서 특정한 암호나 예언을 찾아내는 것보다 위험에 처한 생명의 소중함을 먼저 보는 것이 적절하다."]},{"id":"exo2-3-4","v1":3,"v2":4,"title":"나일강에 놓인 작은 상자","paragraphs":["더 숨길 수 없게 되자 어머니는 갈대 곧 파피루스로 만든 상자에 역청과 나무진을 발라 물이 스며들지 않도록 하고, 아이를 그 안에 눕혀 강가 갈대 사이에 놓았다. 여기에는 절박함과 세심한 돌봄이 함께 들어 있다. 아이를 강에 버리라는 왕의 명령과 달리 어머니는 강 속으로 가라앉지 않도록 상자를 마련한다.","상자를 가리키는 히브리어 תֵּבָה(테바)는 창세기의 노아 방주를 가리킬 때에도 사용되는 낱말이다. 두 이야기의 규모는 다르다. 하나는 홍수 가운데 생명을 보존하는 큰 방주이고, 다른 하나는 강가에 놓인 작은 상자다. 그럼에도 위험한 물 위에서 생명을 지키는 그릇이라는 공통점은 정경적 연결을 풍부하게 한다. 이는 두 사건이 모든 세부에서 같다는 뜻이 아니라, 죽음의 물 한가운데 생명이 보존되는 이야기의 울림이다.","Tyndale 주석은 파피루스가 나일강 삼각주 부근의 수로에서 쉽게 구할 수 있는 가볍고 유연한 재료였다고 설명한다. 이런 배경은 어머니의 선택이 허황된 장치가 아니라 당시 환경에서 가능한 행동이었음을 이해하도록 돕는다. 그러나 그녀가 공주의 목욕 장소를 정확히 알고 계산하여 상자를 놓았는지는 본문이 말하지 않는다. 그 가능성을 확정된 계획처럼 읽을 이유는 없다.","아이의 누이는 멀리 서서 어떻게 되는지 살핀다. 이 짧은 문장은 가족의 행동이 상자를 놓는 순간 끝나지 않았음을 보여 준다. 작은 생명을 향한 가족의 관심이 물가에 계속 머무른다."]},{"id":"exo2-5-6","v1":5,"v2":6,"title":"바로의 집 안에서 시작된 반전","paragraphs":["뜻밖의 인물이 등장한다. 바로의 딸이 강으로 내려와 목욕하다가 갈대 사이의 상자를 발견한다. 이 장면의 긴장은 매우 선명하다. 히브리 남자아이를 없애라는 명령이 나온 곳은 왕의 집이고, 바로 그 집에 속한 여인이 아이를 발견한다. 그는 상자에서 우는 아기를 보고 불쌍히 여긴다. 그리고 그 아이가 히브리 사람의 아들임을 알아본다.","공주가 어떤 종교 의식을 행하기 위해 강에 갔는지, 그가 아이를 구하게 된 감정적·종교적 동기가 무엇이었는지에 대해서는 외부 주석의 여러 설명이 있을 수 있다. 그러나 본문이 분명하게 보여 주는 것은 그가 우는 아기를 보았고, 그를 긍휼히 여겼으며, 히브리 아이인 줄 알면서도 외면하지 않았다는 사실이다. 왕의 명령에 갇혀 있지 않은 긍휼이 왕실 내부에서 나타난다.","이것은 출애굽기 첫머리의 중요한 아이러니다. 바로는 힘으로 이스라엘의 미래를 막으려 하지만, 그가 속한 궁정에서 그 미래와 연결될 아이가 보호를 받기 시작한다. 성경은 이 시점에 하나님의 이름을 직접 언급하지 않으면서도, 뒤따르는 사건들을 통해 독자로 하여금 하나님의 구원 역사가 어디에서 준비되는지를 보게 한다."]},{"id":"exo2-7-9","v1":7,"v2":9,"title":"친어머니에게 돌아온 아이","paragraphs":["아이의 누이가 곧바로 공주에게 다가가 히브리 여인 가운데 젖을 먹일 유모를 불러올지 묻는다. 공주가 허락하자 누이는 아이의 어머니를 데려온다. 죽음의 위험 때문에 아들을 떠나보내야 했던 어머니가, 이번에는 공주의 요청으로 다시 아들을 안고 그를 기르게 된다.","더 놀라운 점은 공주가 수고의 대가까지 약속한다는 사실이다. 죽이라고 명령받은 아이를 친어머니가 다시 기르는데, 그 보호가 왕실의 이름 아래 가능해지는 것이다. 여기에 출애굽기의 깊은 역설이 있다. 압제자의 권력이 의도하지 않았던 방식으로 한 아이의 생존을 뒷받침한다.","이 과정에서 어머니, 누이, 공주와 시녀들은 각기 다른 위치에서 행동한다. 이야기 속 인물들을 단순히 우연의 도구로 지워서는 안 된다. 어머니는 보호할 방법을 찾았고, 누이는 기회를 놓치지 않았으며, 공주는 히브리 아이를 거두었다. 성경은 이 여러 사람의 행위를 통해 구원의 이야기를 전개한다."]},{"id":"exo2-10-10","v1":10,"v2":10,"title":"물에서 건진 아이, 모세","paragraphs":["아이가 자라자 어머니는 그를 바로의 딸에게 데려간다. 공주는 그를 아들로 삼고 '모세'라는 이름을 붙이며, 물에서 건져냈기 때문이라고 설명한다. 히브리어 מָשָׁה(마샤, '끌어내다')와 연결되는 이름 풀이가 본문에 제시된다. 한편 Tyndale 주석은 '모세'가 애굽식 이름 요소와도 관련이 있을 가능성을 소개한다. 이름의 어원에 대한 이러한 설명들은 구별해야 하지만, 본문의 서사적 강조는 확실하다. 그는 물에서 건짐받은 아이로 기억된다.","모세가 왕궁에서 어떠한 교육을 받았는지, 훗날 지도자로 활동할 지식을 얼마나 익혔는지는 이 열 절이 직접 설명하지 않는다. 사도행전 7:22와 연결하여 넓은 정경 안에서 살펴볼 수 있지만, 본문에 없는 구체적인 교육 과정을 상상해 채울 필요는 없다.","출애굽기 2:1–10은 모세가 훗날 이스라엘을 이끌 위대한 인물이 되었다는 사실에서 출발하지 않는다. 죽을 위험에 놓인 한 아이가 어떻게 보존되었는지를 먼저 보여 준다. 출애굽기의 구원은 왕과 군대의 크기를 넘어서는 장엄한 사건이지만, 그 출발점에는 한 어머니의 손길, 누이의 기다림, 이방 공주의 긍휼, 그리고 물 위의 작은 상자가 있었다.","## 본문이 전하는 중심 메시지","바로는 나일강을 생명을 없애는 도구로 삼으려 했다. 그러나 모세는 바로 그 강에서 건져진다. 압제의 명령 아래 위태로워진 생명이 평범한 사람들의 구체적인 행동과 예상 밖의 긍휼을 통해 지켜진 것이다. 하나님은 이 단락에서 직접 말씀하지 않으신다. 그럼에도 앞장에서 이어진 약속과 뒤에 펼쳐질 구원의 역사 속에서, 독자는 아직 드러나지 않은 하나님의 일하심을 바라보게 된다.","어머니와 누이의 행동을 과장하여 모든 일을 처음부터 내다본 완벽한 계획으로 만들 필요도 없고, 공주의 긍휼을 단순한 우연으로 축소할 필요도 없다. 성경은 서로 다른 이들의 선택과 위험이 맞물리는 자리에서 한 생명이 보존되는 사건을 차분히 서술한다. 그 아이가 훗날 백성을 이끌 모세다.","## 더 깊이 읽을 지점","'좋다'(2절)라는 표현은 아이의 외모와 귀함을 나타낼 수 있으며, 아이의 미래를 이미 알고 있었다는 뜻으로 단정하지 않는다. '상자'(3절)는 노아 방주와 같은 히브리어를 사용해 위험한 물 위에서 생명을 보존한다는 정경적 울림을 만든다. 공주의 종교적 동기나 어머니의 구출 계획에 대한 세부는 주석적 가능성이지 본문의 직접 진술은 아니다. 모세의 이름은 본문에서 물에서 건져냄과 연결되지만, 애굽식 이름 배경에 관한 설명은 별개의 어원 논의로 남겨 둔다.","## 사용한 기존 자료","Tyndale Open Study Notes, StudyNotes.xml의 출애굽기 2:1–25 및 2:1–10 해당 항목; unfoldingWord Translation Notes v91, en_tn/tn_EXO.tsv의 2:1–10 해당 항목. 실제 항목과 보유 원본 SHA는 EXODUS_02_01_10_TWO_SOURCE_EVIDENCE_v0.1_CANDIDATE.json에 기록하였다. 외부 자료의 문장을 옮겨 붙이지 않고 본문 중심의 독자용 해설로 재구성하였다."]}],"discoveries":[],"lexicalCards":[],"canonicalLinks":[],"theologicalSynthesis":["'좋다'(2절)라는 표현은 아이의 외모와 귀함을 나타낼 수 있으며, 아이의 미래를 이미 알고 있었다는 뜻으로 단정하지 않는다. '상자'(3절)는 노아 방주와 같은 히브리어를 사용해 위험한 물 위에서 생명을 보존한다는 정경적 울림을 만든다. 공주의 종교적 동기나 어머니의 구출 계획에 대한 세부는 주석적 가능성이지 본문의 직접 진술은 아니다. 모세의 이름은 본문에서 물에서 건져냄과 연결되지만, 애굽식 이름 배경에 관한 설명은 별개의 어원 논의로 남겨 둔다."],"relatedResearch":[],"alternativeReadings":[],"cautions":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"StudyNotes.xml Exod.2.1-10","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"tn_EXO.tsv 2:1-10","license":"CC BY-SA 4.0"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_EXODUS_2_11_22_WORBS_CORE_20261012_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/13시대_인물사건_관계연구/JBC_EXODUS_2_11_22_WORBS_CORE_20261012_01.md","sourceSha256":"0010dccfc65cb6564dce770e01b10af556a9fcaaf018f6d4483f4d4605552147","passage":{"book":"exo","chapter":2,"v1":11,"v2":22,"ref":"출애굽기 2:11–22"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"PASS_WITH_VERIFY","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"구하려던 사람이 도망자가 되다","overview":["바로의 집에서 자란 모세가 장성하여 동족의 고통을 바라본다. 그는 애굽 사람이 히브리 사람을 때리는 것을 보고 그 애굽 사람을 죽인다. 그러나 이튿날 히브리 사람 사이의 다툼에 개입했을 때 돌아온 것은 감사가 아니라 “누가 너를 우리의 지도자와 재판관으로 세웠느냐”는 질문이었다. 사건이 알려지고 바로가 죽이려 하자 모세는 미디안으로 달아난다. 그런데 낯선 땅의 우물가에서 그는 다시 힘없는 사람들을 돕는다. 모세의 삶은 궁정에서 광야로 급격히 바뀌지만, 다른 사람의 고통을 그냥 지나치지 못하는 모습은 이어진다."],"centralMessage":"모세는 동족이 압제받는 것을 보고 외면하지 않았지만, 첫 행동은 살인과 도피로 끝났다. 그는 지도자가 되려는 뜻만으로 지도자가 될 수 없었다. 그러나 낯선 미디안의 우물가에서도 고통받는 사람들을 돕는 모습을 보여 준다. 출애굽기 2:11–22는 모세의 용기를 무조건 찬양하거나 그의 실패만으로 그를 규정하지 않는다. 백성의 고통을 향한 관심이 아직 해결되지 않은 한계를 드러내는 과정과, 새로운 삶의 자리에서 계속되는 모습을 함께 보여 준다. 하나님의 공식적인 부르심은 아직 오지 않았다. 그 사이에서 구원을 갈망하는 인간의 열정과 하나님의 때에 이루어질 구원 사이의 간격이 선명해진다.","literaryStructure":[{"v1":11,"v2":12,"title":"궁정에서 나온 모세, 백성의 고통을 보다"},{"v1":13,"v2":15,"title":"“누가 너를 세웠느냐”라는 질문"},{"v1":15,"v2":17,"title":"미디안 우물가에서 다시 만난 불의"},{"v1":18,"v2":20,"title":"“애굽 사람 하나가 우리를 구해 주었습니다”"},{"v1":21,"v2":22,"title":"낯선 땅의 거류민, 게르솜"}],"sections":[{"id":"exo2-11-12","v1":11,"v2":12,"title":"궁정에서 나온 모세, 백성의 고통을 보다","paragraphs":["출애굽기 2:1–10의 모세는 다른 사람들에게 보호받는 아이였다. 이제 그는 장성하여 궁정의 보호 아래 있는 자신의 삶 바깥으로 걸어 나온다. 본문은 모세가 “자기 형제들”에게 나가 그들의 무거운 노동을 보았다고 말한다. 같은 문장 안에서 그의 친족 관계와 그들의 고통이 만난다. 왕실에서 자랐지만 그는 압제받는 히브리 사람들을 자신과 무관한 사람들이라고 여기지 않는다.","곧 한 애굽 사람이 히브리 사람을 때리는 장면이 등장한다. 모세는 이쪽저쪽을 살펴 사람이 없는 것을 확인한 뒤 그 애굽 사람을 쳐 죽이고 모래 속에 감춘다. 여기서 본문은 모세의 동기를 길게 설명하지 않는다. 동족의 억울함을 보았다는 사실은 분명하지만, 사람을 죽이고 숨겼다는 사실 역시 그대로 남는다. 억압을 보고 분노했다는 이유만으로 이 행동 전체를 의로운 구원 행위로 승인할 수는 없다.","Tyndale 주석은 이 장면에서 모세의 용기와 동족에 대한 관심을 인정하는 동시에, 스스로 구원을 이루려 했던 성급함을 지적한다. 이 설명은 유익하지만, 하나님이 이때 모세에게 어떠한 구체적 행동 지침을 주셨는지는 본문에 기록되지 않았다는 점도 기억해야 한다. 아직 모세에게 하나님의 공식적인 소명이 주어지는 장면은 출애굽기 3장에 남아 있다."]},{"id":"exo2-13-15","v1":13,"v2":15,"title":"“누가 너를 세웠느냐”라는 질문","paragraphs":["다음날 모세는 이번에는 두 히브리 사람이 서로 싸우는 모습을 본다. 그는 잘못한 사람에게 왜 동족을 치느냐고 묻는다. 어제는 애굽인의 폭력에 개입했고, 오늘은 자기 백성 안의 폭력을 멈추려 한다. 모세가 관심을 가진 것은 단순히 민족 사이의 대립만이 아니다. 힘을 사용해 다른 사람을 해치는 행동 자체가 문제로 나타난다.","하지만 상대는 모세에게 “누가 너를 우리를 다스리는 사람과 재판관으로 세웠느냐”고 반문한다. 이 질문은 훗날 모세가 백성을 인도하게 된다는 사실을 아는 독자에게 특히 중요하게 들린다. 모세에게는 고통을 보는 눈과 행동하려는 의지가 있었지만, 아직 그가 백성을 이끌 권위를 부여받았다는 이야기는 없다. 동족을 위한 열정과 공동체가 인정하는 지도력은 같은 것이 아니다.","그 사람은 모세가 애굽 사람을 죽인 일을 언급한다. 감춘 사건이 알려졌음을 깨달은 모세는 두려워한다. 바로 또한 이 일을 듣고 그를 죽이려 한다. 물에서 건져져 왕궁의 보호를 받았던 아이가 이제 바로의 추적을 피해야 하는 도망자가 되었다. 출애굽기 1장에서 죽음의 위협을 내리던 바로의 권력이 이번에는 장성한 모세 개인을 향한다.","모세의 첫 개입은 이스라엘의 해방으로 이어지지 않는다. 오히려 그의 삶을 완전히 뒤바꾼다. 이는 그가 백성의 고통을 잘못 보았기 때문이 아니라, 그 고통을 해결하는 방식과 지도자의 소명이 아직 온전히 갖추어지지 않았음을 보여 주는 서사적 전환점이다."]},{"id":"exo2-15-17","v1":15,"v2":17,"title":"미디안 우물가에서 다시 만난 불의","paragraphs":["모세는 애굽을 떠나 미디안 땅에 머물다가 우물가에 앉는다. Tyndale 주석은 미디안을 시나이 남부와 아라비아반도 서북부를 포함하는 지역과 연결하여 소개한다. 이 설명은 도망자가 애굽의 권력으로부터 멀리 떠났다는 배경을 제공하지만, 이 짧은 본문만으로 모세가 머문 우물의 정확한 위치까지 확정할 수는 없다.","미디안 제사장의 일곱 딸이 양 떼에게 물을 먹이려 물을 길어 구유에 채운다. 그러나 다른 목자들이 와서 그들을 쫓아낸다. 우물가의 사건은 애굽에서 보았던 압제를 작은 규모로 되풀이한다. 누군가가 자신의 힘을 이용하여 다른 사람의 정당한 일을 가로막는다.","모세는 일어나 그들을 구해 주고 양 떼에게 물까지 먹인다. 여기서 '구하다'는 의미의 표현은 출애굽 이야기 전체에서 중요한 울림을 가진다. 모세는 애굽에서는 폭력적인 방법으로 개입해 살인자가 되었지만, 미디안에서는 쫓겨난 여성들을 돕고 일상적인 필요까지 채워 준다. 둘 다 다른 사람의 어려움을 외면하지 못했다는 공통점이 있지만, 두 사건의 행위와 결과를 동일하게 평가할 수는 없다.","이 장면에서 모세는 아직 이스라엘의 공인된 지도자가 아니다. 그럼에도 낯선 사람들의 위기에 적극적으로 대응한다. 그의 인생이 중단된 듯한 도피의 자리에서도 타인을 향한 관심은 사라지지 않는다."]},{"id":"exo2-18-20","v1":18,"v2":20,"title":"“애굽 사람 하나가 우리를 구해 주었습니다”","paragraphs":["딸들이 평소보다 빨리 집에 돌아오자 아버지 르우엘은 그 이유를 묻는다. 딸들은 한 “애굽 사람”이 목자들의 손에서 자기들을 구하고 양 떼에게 물까지 먹였다고 대답한다. 흥미로운 것은 그들이 모세를 애굽 사람으로 인식했다는 사실이다. 모세는 스스로는 히브리 사람을 자기 형제로 보았지만, 낯선 이들의 눈에는 애굽 사람으로 보인다. 왕궁의 문화 속에서 자란 그의 정체성과 출신의 긴장이 이 한마디에 드러난다.","르우엘은 그 사람을 어디에 두고 왔느냐며 초대해 식사를 대접하라고 한다. 모세는 우물가에서 도움을 베풀었고, 이제 타인의 환대를 받는다. 출애굽기의 이야기는 이 장면을 거대한 기적이나 공식적인 소명으로 꾸미지 않는다. 낯선 곳에서 살아가는 한 사람에게 필요한 보호와 관계가 조용히 마련되는 모습으로 이어 간다."]},{"id":"exo2-21-22","v1":21,"v2":22,"title":"낯선 땅의 거류민, 게르솜","paragraphs":["모세는 그 가족과 함께 살기로 하고 르우엘의 딸 십보라와 결혼한다. 아들이 태어나자 그는 게르솜이라 이름 지으며 자신이 낯선 땅에서 거류민이 되었다고 설명한다. 이 이름에 붙은 설명은 단순히 새로운 주소를 알려 주는 말이 아니다. 왕궁의 보호를 떠나 새로운 가정을 이루었지만, 모세는 자신의 처지를 여전히 낯선 땅에 머무는 사람으로 이해한다.","히브리어의 '거류민'을 뜻하는 게르(גֵּר)라는 표현을 떠올리면 이 이름의 무게가 더 잘 느껴진다. 이스라엘 또한 애굽에서 이방 땅의 나그네로 살아왔다. 이제 백성의 고통을 보았던 모세 자신이 낯선 땅에서 거류민의 삶을 살고 있다. 모세가 겪은 도피와 가족 형성은 이스라엘 전체의 나그네 경험과 주제적으로 맞닿는다.","여기서 성경은 모세가 자신의 실패를 모두 극복했거나, 지도자로서 완벽히 준비되었다고 선언하지 않는다. 오히려 그는 아직 미디안에 머무는 사람이고, 이스라엘은 여전히 애굽에서 고통받고 있다. 2장 마지막 부분에서 그들의 부르짖음이 하나님께 올라가고, 3장에서 하나님이 모세를 부르실 때 비로소 새로운 전환이 열린다.","## 본문이 전하는 중심 메시지","모세는 동족이 압제받는 것을 보고 외면하지 않았지만, 첫 행동은 살인과 도피로 끝났다. 그는 지도자가 되려는 뜻만으로 지도자가 될 수 없었다. 그러나 낯선 미디안의 우물가에서도 고통받는 사람들을 돕는 모습을 보여 준다. 출애굽기 2:11–22는 모세의 용기를 무조건 찬양하거나 그의 실패만으로 그를 규정하지 않는다. 백성의 고통을 향한 관심이 아직 해결되지 않은 한계를 드러내는 과정과, 새로운 삶의 자리에서 계속되는 모습을 함께 보여 준다. 하나님의 공식적인 부르심은 아직 오지 않았다. 그 사이에서 구원을 갈망하는 인간의 열정과 하나님의 때에 이루어질 구원 사이의 간격이 선명해진다.","## 자료와 연구 계보","연구 유형: 기존 승인 WORBS CORE 직접 재사용이 아닌 **신규 WORBS 자체 본문 의미 연구**. 본문 구조와 중심 질문, 2:11–15 및 2:16–22의 대응, 모세의 정체성과 지도권 문제, 게르솜 이름의 서사적 의미는 이번 연구에서 직접 구성했다.","보강 근거: Tyndale Open Study Notes, StudyNotes.xml의 Exod.2.1-25, 2.11-15, 2.11-12, 2.13, 2.14, 2.15, 2.16-25, 2.16, 2.17, 2.18-20 관련 항목; unfoldingWord Translation Notes v91의 tn_EXO.tsv 2:11–22 항목. 특정 지리 위치, 모세의 내적 동기나 교육을 본문이 말한 사실처럼 확정하지 않는다. 근거 기록: EXODUS_02_11_22_TWO_SOURCE_EVIDENCE_v0.1_CANDIDATE.json."]}],"discoveries":[{"id":"exo2-11-family","domain":"literary","title":"“자기 형제들”을 보러 나온 궁정의 아들","paragraphs":["11절은 모세가 애굽 왕실의 보호를 받았으면서도 히브리 사람들을 “자기 형제들”로 인식했음을 보여 준다. 출애굽기 2:1–10의 구출받는 아이가 이제 다른 사람들의 고통을 보는 사람으로 전환된다."],"evidence":["출 2:11","출 2:1–10"]},{"id":"exo2-14-authority","domain":"original_language","title":"관심과 권위는 같은 것이 아니다","paragraphs":["“누가 너를 지도자와 재판관으로 세웠느냐”(14절)는 질문의 요점은 모세에게 지도권을 부여한 이가 누구냐는 데 있다. 그가 억압을 보았다는 사실과 폭력을 행했다는 사실을 분리해 읽어야 한다. 출애굽기 3장의 하나님의 소명은 이 질문과 문학적 긴장을 만든다."],"evidence":["출 2:12–14","출 3:10–12"]},{"id":"exo2-17-rescue","domain":"literary","title":"애굽의 폭력, 미디안의 구출","paragraphs":["앞 장면에서 모세의 개입은 살인과 도피로 끝나지만, 17절에서 그는 목자들에게 밀려난 여성들을 구하고 물까지 길어 준다. 두 사건은 약자를 외면하지 않는 인물의 일관성과 행동의 방식이 갖는 차이를 동시에 보여 준다."],"evidence":["출 2:11–12","출 2:16–17"]},{"id":"exo2-22-identity","domain":"theology","title":"애굽인으로 불린 히브리인, 낯선 땅의 거류민","paragraphs":["미디안 여성들은 모세를 “애굽 사람”이라고 부르지만(19절), 모세는 아들 이름을 지으며 자신이 낯선 땅의 거류민이라고 설명한다(22절). 이 두 표현은 모세의 복합적인 소속과 소외를 드러내며, 애굽에 머문 이스라엘의 처지와 주제적으로 이어진다."],"evidence":["출 2:19","출 2:22","창 15:13"]}],"lexicalCards":[{"verse":11,"form":"אֶחָיו","lemma":"אָח","pronunciation":"에하브 (ʾeḥāw)","gloss":"그의 형제들 — 모세가 동족으로 인식한 히브리인들"},{"verse":12,"form":"וַיַּךְ","lemma":"נָכָה","pronunciation":"바야크 (wayyak)","gloss":"그가 쳤다 — 이 문맥에서는 애굽인을 쳐 죽인 행동"},{"verse":14,"form":"שַׂר וְשֹׁפֵט","lemma":"שַׂר / שֹׁפֵט","pronunciation":"사르 베쇼페트 (śar wəšōp̄ēṭ)","gloss":"통치자와 재판관 — 누가 모세에게 권한을 주었는가"},{"verse":17,"form":"וַיּוֹשִׁעָן","lemma":"יָשַׁע","pronunciation":"바요쉬안 (wayyōšīʿān)","gloss":"그가 그들을 구해 주었다 — 쫓겨난 여성들을 도와 보호함"},{"verse":22,"form":"גֵּר","lemma":"גֵּר","pronunciation":"게르 (gēr)","gloss":"거류민 — 낯선 땅에 머무는 자신의 처지"}],"canonicalLinks":[{"ref":"사도행전 7:23–29","note":"연결 주제: 동족을 돌보려던 모세의 첫 개입과 거절. 스데반은 하나님이 모세를 통해 구원하시려는 뜻을 동족이 이해하지 못했다고 회고한다. 출애굽기의 “누가 너를 세웠느냐”라는 반문을 후대의 구원사적 해석 속에서 읽게 한다."},{"ref":"히브리서 11:24–26","note":"연결 주제: 모세의 소속 선택. 히브리서는 모세가 애굽 왕궁의 특권보다 하나님의 백성과 함께하는 길을 택한 믿음을 강조한다. 출애굽기 2:11에서 동족의 고통을 바라본 선택을 더 넓은 정경 맥락에서 조명한다."},{"ref":"출애굽기 3:1–12","note":"연결 주제: 인간의 첫 구원 시도와 하나님의 소명. 출 2:14에서는 모세를 누가 지도자로 세웠는지가 문제였지만 출 3장에서 하나님이 그를 보내신다. 두 장을 연결하면 구원자의 열심과 부르심을 구별할 수 있다."},{"ref":"출애굽기 18:13–27","note":"연결 주제: 지도자와 재판관의 실제 역할. 출 2:14에서 부정당했던 판단·지도 권한은 훗날 백성을 위한 재판 업무와 공동체적 책임의 문제로 나타난다. 두 장면은 모세의 지도력이 발전하는 과정을 보게 한다."},{"ref":"창세기 15:13–14; 출애굽기 2:22–25","note":"연결 주제: 거류민의 삶과 구원의 때. 조상의 후손이 낯선 땅에서 고통받으리라는 말씀은 모세가 스스로를 거류민이라 부르는 장면과 울림을 이룬다. 이어지는 백성의 부르짖음은 하나님의 응답을 준비한다."}],"theologicalSynthesis":["본문은 모세의 동족에 대한 관심을 분명히 보여 주지만, 그것이 곧 살인을 정당화하지는 않는다. 압제를 보았다는 사실, 폭력적 대응, 지도권을 인정받지 못한 현실을 함께 읽을 때 인간의 구원 열정과 그 한계가 동시에 드러난다.","모세가 애굽에서 미디안으로 도망한 뒤에도 낯선 여성들의 억울함을 외면하지 않은 장면은 그의 성품과 변화의 여지를 보여 준다. 그러나 아직 하나님이 모세를 공식적으로 보내셨다는 선언은 나오지 않는다. 독자는 3장의 소명을 기다리게 된다.","모세는 히브리 사람을 형제로 여기면서도 미디안에서는 애굽 사람으로 불리고, 자신의 아들을 통해서는 스스로 거류민임을 고백한다. 출애굽기의 구원은 이렇게 복합적이고 불안정한 삶의 자리 속에서 준비된다."],"relatedResearch":[],"alternativeReadings":[],"cautions":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"StudyNotes.xml Exod.2.11-22","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"tn_EXO.tsv 2:11-22","license":"CC BY-SA 4.0"}]},{"title":"부르짖음이 올라가고, 하나님이 언약을 기억하시다","overview":["모세가 미디안에 머무는 동안 애굽 왕이 죽지만, 이스라엘의 고역은 끝나지 않는다. 백성의 탄식과 부르짖음이 하나님께 올라간다. 이야기는 이제 하나님이 들으시고 언약을 기억하시고 보시고 아신다는 네 동사로 집중된다. 아직 구원은 실행되지 않았지만 구원 이야기의 중심 행위자가 누구인지는 분명해진다."],"centralMessage":"왕의 교체가 고통을 해결하지 못했으나 언약의 하나님은 백성의 신음을 들으시고 그들의 현실을 아신다. 조상 언약의 기억은 망각의 회복이 아니라 구원 행동의 근거를 밝힌다. 이 짧은 단락은 출애굽기 3장의 소명을 준비하는 전환점이다.","literaryStructure":[{"v1":23,"v2":23,"title":"왕의 죽음과 끝나지 않은 고역"},{"v1":24,"v2":24,"title":"들으심과 언약의 기억"},{"v1":25,"v2":25,"title":"보심과 아심의 열린 결말"}],"sections":[{"id":"exo2-23","v1":23,"v2":23,"title":"왕이 죽었지만 고역은 끝나지 않았다","paragraphs":["많은 날이 지났고 애굽 왕이 죽었다. 이는 모세의 미디안 생활과 애굽 백성의 현실을 다시 연결하는 시간 전환이다. 그러나 통치자의 죽음은 고역의 종말이 아니다. 백성은 여전히 강제노동 때문에 탄식한다.","부르짖음이 하나님께 올라갔다는 표현은 물리적인 소리의 이동이 아니라 억눌린 백성의 호소가 하나님 앞에 이르렀다는 서사적 이미지이다. 모든 사람이 같은 형식의 기도를 했다고 단정할 수는 없다. 모세의 미완성된 첫 구원 시도에서 시선이 이스라엘 전체의 고통으로 돌아온다."]},{"id":"exo2-24","v1":24,"v2":24,"title":"하나님이 들으시고 언약을 기억하시다","paragraphs":["하나님이 신음을 들으셨다는 표현은 단순한 소리의 인지에 머물지 않는다. 곧 이어지는 언약의 기억과 연결되어 백성의 고통을 관계적으로 아시는 하나님을 보여 준다.","아브라함·이삭·야곱의 이름은 족보 장식이 아니다. 창세기의 후손과 땅, 하나님의 지속적인 관계에 관한 약속을 불러온다. 기억하다(זָכַר)는 이 문맥에서 언약을 행동의 근거로 고려한다는 뜻을 담는다. 하나님이 잊었다가 뒤늦게 떠올렸다는 의미로 단정하지 않는다."]},{"id":"exo2-25","v1":25,"v2":25,"title":"하나님이 보시고 아시다","paragraphs":["하나님이 이스라엘 자손을 보셨고 하나님이 아셨다고 끝난다. 마지막 알다(יָדַע) 뒤에는 목적어가 없다. 그들의 형편을 아셨다는 번역은 자연스러운 문맥 보충이지만 원문에 적힌 목적어는 아니다.","24–25절의 네 번의 하나님과 듣다·기억하다·보다·알다는 시간표의 네 단계가 아니라 하나님의 언약적 관심을 여러 측면에서 강조한다. 출애굽기 3:7에서 하나님이 보시고 들으시고 아신다고 말씀하실 때, 이 열린 결말은 구원의 소명으로 이어진다."]}],"lexicalCards":[{"verse":23,"form":"וַיִּזְעָקוּ","lemma":"זָעַק","pronunciation":"바이즈아쿠 (wayyizʿăqû)","gloss":"그들이 부르짖었다","morphology":"칼 연속 서술형, 3인칭 복수","meaning":"고역 때문에 터져 나온 절박한 외침. 같은 절의 탄식(אָנַח)과 함께 고통을 표현한다.","interpretiveContribution":"백성의 고통이 하나님께 이르는 호소로 전환됨을 보여 준다."},{"verse":24,"form":"וַיִּשְׁמַע","lemma":"שָׁמַע","pronunciation":"바이쉬마 (wayyišmaʿ)","gloss":"그가 들었다","morphology":"칼 연속 서술형, 3인칭 단수","meaning":"하나님이 신음을 들으심. 이어지는 언약 기억과 연결된다.","interpretiveContribution":"압제의 소리가 하나님 앞에서 무시되지 않음을 보여 준다."},{"verse":24,"form":"וַיִּזְכֹּר","lemma":"זָכַר","pronunciation":"바이즈코르 (wayyizkōr)","gloss":"그가 기억했다","morphology":"칼 연속 서술형, 3인칭 단수","meaning":"조상 언약을 유효한 약속으로 고려하심. 건망증을 전제하지 않는다.","interpretiveContribution":"구원의 근거를 언약의 신실함에 둔다."},{"verse":25,"form":"וַיַּרְא","lemma":"רָאָה","pronunciation":"바야르 (wayyarʾ)","gloss":"그가 보았다","morphology":"칼 연속 서술형, 3인칭 단수","meaning":"이스라엘의 고통을 보시는 하나님을 드러낸다.","interpretiveContribution":"3:7의 하나님의 직접 말씀과 연결된다."},{"verse":25,"form":"וַיֵּדַע","lemma":"יָדַע","pronunciation":"바예다 (wayyēdaʿ)","gloss":"그가 알았다","morphology":"칼 연속 서술형, 3인칭 단수","meaning":"마지막 동사의 목적어는 명시되지 않는다. 형편을 아셨다는 말은 문맥 보충이다.","interpretiveContribution":"하나님의 앎과 뒤따를 구원 행동 사이에 기대를 만든다."}],"discoveries":[{"id":"exo223-king","domain":"literary","title":"왕의 죽음과 계속되는 노역","paragraphs":["통치자의 교체와 백성의 구원은 동일하지 않다. 이 대비는 하나님이 주어가 되는 다음 절의 무게를 더한다."],"evidence":["출 2:23","출 1:11–14"]},{"id":"exo223-cry","domain":"original_language","title":"탄식에서 하나님께 이르는 호소","paragraphs":["탄식과 부르짖음은 고통의 깊이를 표현한다. 하나님께 올라갔다는 표현은 공간적 이동이 아닌 서사적 이미지이다."],"evidence":["출 2:23"]},{"id":"exo224-covenant","domain":"canonical","title":"고통 속에 다시 등장하는 조상 언약","paragraphs":["아브라함·이삭·야곱의 이름은 출애굽이 창세기 언약의 연속선에 있음을 밝힌다."],"evidence":["출 2:24","창 15:13–14"]},{"id":"exo225-four","domain":"literary","title":"네 번의 하나님과 네 동사","paragraphs":["들으심·기억하심·보심·아심은 하나님의 언약적 관심을 입체적으로 보여 주는 집중 서술이다."],"evidence":["출 2:24–25"]},{"id":"exo225-open","domain":"translation","title":"목적어 없는 마지막 아심","paragraphs":["원문 마지막 동사에는 목적어가 없으며 그들의 형편을이라는 번역은 문맥 보충이다. 3:7을 기다리게 하는 열린 결말이다."],"evidence":["출 2:25","출 3:7"]}],"canonicalLinks":[{"ref":"창세기 15:13–14","reason":"타국의 고역과 이후의 구원을 예고하는 조상 언약 문맥","message":"아브라함의 후손은 고난 뒤에 나올 것이다.","significance":"고난이 약속의 폐기를 뜻하지 않음을 보여 준다."},{"ref":"창세기 17:7; 출애굽기 1:1–7","reason":"세대를 잇는 언약과 야곱 가족의 번성","message":"하나님은 후손과의 언약 관계를 유지하신다.","significance":"번성과 고통이 하나의 언약 이야기 안에 놓인다."},{"ref":"출애굽기 3:7–10","reason":"보다·듣다·알다의 어휘와 모세 소명의 직접 연결","message":"하나님이 고통을 아시고 모세를 보내신다.","significance":"2:23–25의 서술이 구체적인 구원 행동으로 이어진다."},{"ref":"출애굽기 6:5–8","reason":"신음·듣다·기억하다·언약의 반복","message":"하나님이 언약을 기억하여 구출을 선언하신다.","significance":"기억은 단순 회상 이상의 신실한 행동과 연결된다."},{"ref":"시편 105:8–11, 42–43","reason":"조상 언약의 기억과 출애굽의 정경적 회고","message":"하나님은 조상과 맺은 언약을 기억하셨다.","significance":"후대의 찬양은 출애굽을 언약 성취로 해석한다."}],"theologicalSynthesis":["하나님의 구원 이야기는 현실의 고난을 생략하지 않는다. 끝나지 않은 고역과 탄식이 먼저 기록되고, 그 현실을 들으시고 보시는 하나님이 뒤따른다.","하나님의 언약 기억은 세대와 통치자가 바뀌어도 약속이 사라지지 않는 신실함을 드러낸다. 구원의 근거는 정치적 변화보다 하나님과 백성의 관계에 있다.","이 단락은 즉각적인 문제 해결을 약속하지 않는다. 아직 고난이 끝나지 않았어도 언약의 하나님은 자기 백성을 외면하지 않으신다는 사실을 밝히며 3장의 소명을 준비한다."],"alternativeReadings":[{"question":"하나님이 언약을 기억하셨다는 말은 잊으셨다는 뜻인가?","assessment":"망각의 회복보다 언약을 행동의 근거로 삼는 관계적 표현이다.","status":"RESOLVED_CONTEXTUALLY"},{"question":"2:25의 아셨다의 목적어는 무엇인가?","assessment":"히브리어에는 명시되지 않는다. 그들의 형편을이라는 보충은 문맥 해석이다.","status":"VERIFY_NONBLOCKING"}],"cautions":["많은 날이라는 표현으로 정확한 연수를 계산하지 않는다.","부르짖음이 올라갔다는 표현을 물리적 이동으로 읽지 않는다.","네 동사를 시간표의 네 단계로 강제하지 않는다.","2:25의 목적어는 원문에 명시되지 않는다."],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"StudyNotes.xml Exod.2.1-25; Exod.2.24-25","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"tn_EXO.tsv 2:23–24","license":"CC BY-SA 4.0"}],"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"EXODUS_02_23_25_WORBS_CORE_v0.1_CANDIDATE","sourcePath":"G:\\내 드라이브\\Jude_Lee_OS\\01_PROJECTS\\01_목회연구_WORBS_BICS\\WORKING_COMMENTARY66_20261011\\EXODUS_02_23_25_WORBS_CORE_v0.1_CANDIDATE.md","sourceSha256":"22e266bfc36c3fce903d7e51959afa327409a3516a44b45c41694c501f43009b","passage":{"book":"exo","chapter":2,"v1":23,"v2":25,"ref":"출애굽기 2:23–25"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"PASS_WITH_VERIFY","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","relatedResearch":[]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_EXODUS_03_01_12_WORBS_READERS_20261013_01","researchVersion":"v0.3","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/EXODUS_03_01_12_WORBS_READERS_v0.3_CAPTAIN_APPROVED_20261013.md","sourceSha256":"6a33e0df0e5a46a73753355877a3633609335c20d0d1416c528cb27645da8651","passage":{"book":"exo","chapter":3,"v1":1,"v2":12,"ref":"출애굽기 3:1–12"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CAPTAIN_CONTENT_APPROVED_PENDING_PROJECT01_QA","qualityStatus":"REQUIRES_PROFESSIONAL_VALIDATION","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"불꽃을 보러 갔다가 하나님의 부르심을 듣다","overview":["불꽃, 부르심, 고통, 파송을 따라가는 출애굽기 3:1–12의 이야기식 주석."],"centralMessage":"하나님은 고통받는 백성을 보시고 모세를 부르시며 자신의 동행을 약속하신다.","literaryStructure":[{"title":"광야의 평범한 하루가 멈추다","v1":1,"v2":3},{"title":"불꽃보다 먼저 들려온 이름","v1":4,"v2":6},{"title":"애굽의 고통이 광야에서 들리다","v1":7,"v2":9},{"title":"“내가 내려가겠다.” 그런데 “네가 가라.”","v1":10,"v2":12}],"sections":[{"id":"exo3-v03-1-3","v1":1,"v2":3,"title":"광야의 평범한 하루가 멈추다","paragraphs":["모세는 미디안에서 양 떼를 돌보고 있었다. 한때 애굽 왕궁에서 살았던 그는 이제 장인의 양 떼를 치는 목자가 되어 있었다. 출애굽기 2장에서 그는 동족이 억압받는 모습을 보고 애굽 사람을 쳤다가 결국 애굽을 떠나야 했다. 그가 다시 등장하는 곳은 애굽의 궁전도, 이스라엘 백성의 거주지도 아닌 광야이다.","그날 모세는 양 떼를 이끌고 광야의 뒤편으로 가다가 호렙에 이르렀다. 성경은 그곳을 ‘하나님의 산’이라고 부른다. 앞으로 이 산이 이스라엘 역사에서 얼마나 중요한 장소가 될 것인지 독자는 차츰 알게 된다. 그러나 지금 모세에게 그곳은 양 떼를 이끌고 도착한 광야의 한 장소이다.","그런데 그곳에서 이상한 광경이 눈에 들어왔다.","떨기나무에 불이 붙어 있었다. 불꽃이 타오르는데도 나무는 타서 없어지지 않았다. 모세는 그냥 지나가지 않았다. 그는 걸음을 돌려 그 광경을 자세히 살펴보려 했다.","여기서 성경은 모세가 불꽃을 바라본 다음 왜 걸음을 돌렸는지를 분명히 들려준다. 타면서도 사라지지 않는 나무의 신비를 알고 싶었던 것이다. 하지만 독자가 이 장면에서 만나게 되는 더 놀라운 사건은 나무의 특이한 성질에 있지 않다.","그가 불꽃을 보러 다가갔을 때, 그곳에서 누군가 그의 이름을 부르셨기 때문이다."]},{"id":"exo3-v03-4-6","v1":4,"v2":6,"title":"불꽃보다 먼저 들려온 이름","paragraphs":["모세가 다가오는 것을 하나님이 보셨다.","그리고 불꽃 가운데서 그의 이름을 부르셨다.","“모세야, 모세야.”","모세는 “내가 여기 있나이다”라고 대답했다.","모세는 나무를 살펴보려고 걸음을 돌렸지만, 이야기는 그가 보고자 했던 대상으로부터 그를 부르시는 하나님에게로 옮겨 간다. 지금까지는 모세가 보고 있었다. 이제는 하나님이 모세를 보셨다는 사실이 드러난다.","하나님은 먼저 가까이 오지 말라고 말씀하신다. 그리고 모세가 서 있는 곳이 거룩한 땅이므로 발에서 신을 벗으라고 명령하신다.","모세가 발견한 것은 자유롭게 살펴보고 설명할 수 있는 자연의 신기한 현상이 아니었다. 자신을 부르시고 자신의 접근을 제한하실 수 있는 거룩한 하나님의 임재였다.","그 땅이 거룩한 이유는 광야의 흙 자체에 특별한 능력이 있기 때문이 아니다. 하나님이 그 자리에서 모세를 만나고 계시기 때문이다. 신을 벗으라는 말씀은 모세가 이제 누구 앞에 서 있는지를 드러낸다.","그런데 하나님은 자신을 전혀 낯선 신으로 소개하지 않으신다.","아브라함의 하나님, 이삭의 하나님, 야곱의 하나님이라고 말씀하신다.","이 이름들이 등장하는 순간, 광야의 이야기는 오래전 족장들에게 주셨던 하나님의 약속과 연결된다. 출애굽기 2장 마지막에서 언약을 기억하신 하나님이 바로 지금 모세를 부르고 계신 것이다.","모세는 얼굴을 가렸다. 처음에는 불꽃을 더 자세히 살펴보려고 다가갔던 사람이 이제 하나님을 바라보기를 두려워한다.","이 장면에서 모세의 시선은 크게 달라진다. 처음에는 이상한 나무를 보고 있었지만, 이제 그는 자신의 조상들에게 약속하셨던 하나님 앞에 서 있다.","그리고 그 하나님이 자신을 부르신 이유를 듣게 된다."]},{"id":"exo3-v03-7-9","v1":7,"v2":9,"title":"애굽의 고통이 광야에서 들리다","paragraphs":["하나님이 모세에게 말씀하시는 첫 번째 중요한 소식은 모세 자신의 미래에 관한 것이 아니었다.","애굽에 있는 이스라엘 백성에 관한 것이었다.","하나님은 자기 백성이 고통받는 것을 보셨고, 그들의 부르짖음을 들으셨으며, 그들의 고난을 알고 계신다고 말씀하신다.","이 장면을 이해하려면 출애굽기 2장의 마지막으로 돌아갈 필요가 있다. 그곳에서 이스라엘 자손은 고된 노동 때문에 탄식했고, 하나님은 그들의 부르짖음을 들으셨다. 하나님이 언약을 기억하시고 그들을 보셨다는 사실을 독자는 이미 알고 있다.","그러나 이스라엘 백성은 아직 그 고통에서 벗어나지 못했다.","하나님의 기억과 백성의 해방 사이에는 아직 이야기가 남아 있었다.","이제 하나님은 광야에서 모세를 부르시고, 그동안 백성에게 일어난 일을 자신이 어떻게 알고 계셨는지 직접 말씀하신다.","특히 7절에서 하나님은 단순히 ‘보았다’고 말씀하지 않으신다. 히브리어는 ‘보다’라는 동사를 두 형태로 나란히 사용하여 그 사실을 강하게 강조한다. ‘분명히 보았다’는 뜻이다.","백성의 고통은 하나님께 희미하게 전달된 소식이 아니었다.","하나님은 그들의 형편을 확실하게 보고 계셨다.","그러나 하나님의 말씀은 그들을 보고 계셨다는 선언에서 끝나지 않는다.","하나님은 그들을 애굽인의 손에서 건져 내기 위해 내려가겠다고 말씀하신다. 그리고 그들을 좋은 땅, 넓은 땅, 젖과 꿀이 흐르는 땅으로 인도하겠다고 약속하신다.","‘내려가겠다’는 말은 하나님이 그때까지 애굽의 상황을 모르셨다는 의미가 아니다. 이제 그들의 고난에 직접 개입하여 구원의 일을 행하시겠다는 선언이다.","처음에는 광야의 한 떨기나무에서 시작된 이야기였다. 그러나 하나님이 말씀하시자 그 이야기 안에 애굽의 수많은 백성과 그들의 부르짖음, 오래전 조상들에게 주셨던 약속, 그리고 앞으로 그들이 향할 땅이 함께 들어온다.","모세가 보러 왔던 것은 불꽃이었다.","그런데 하나님이 모세에게 보여 주시는 것은 고통받는 자기 백성을 향한 하나님의 뜻이었다.","그리고 바로 여기에서 이야기의 방향이 다시 한번 바뀐다."]},{"id":"exo3-v03-10-12","v1":10,"v2":12,"title":"“내가 내려가겠다.” 그런데 “네가 가라.”","paragraphs":["하나님은 앞서 분명히 말씀하셨다.","자신이 내려가서 이스라엘을 구원하겠다는 것이다.","그런데 곧이어 모세에게 말씀하신다.","“이제 가라.”","하나님은 모세를 바로에게 보내어 이스라엘 자손을 애굽에서 이끌어 내게 하시겠다고 말씀하신다.","이 두 말씀을 이어서 읽으면 중요한 사실이 드러난다.","하나님이 친히 구원하시겠다고 선언하셨는데, 그 일을 위해 한 사람을 보내신다. 하나님의 구원은 모세와 무관하게 이루어지는 일이 아니며, 그렇다고 구원의 책임이 모세 혼자에게 넘겨진 것도 아니다.","하나님은 자신의 뜻을 이루시는 과정에 모세를 부르신다.","이것은 모세의 과거를 다시 떠올리게 한다.","출애굽기 2장에서 모세는 동족을 돕기 위해 직접 행동했다. 그러나 그의 행동은 살인과 도피로 이어졌다. 한 히브리 사람은 그에게 누가 그를 지도자와 재판관으로 세웠느냐고 물었다.","그 질문은 애굽에서 모세가 자신의 힘으로 행동하던 시절에 제기되었다.","그런데 이제 광야에서 그를 보내시는 분은 하나님 자신이다.","출애굽기 2장과 3장은 모세가 이스라엘의 고통과 다시 연결되는 두 장면을 보여준다. 첫 번째 장면에서 모세는 스스로 개입했다. 두 번째 장면에서는 하나님이 그를 보내신다.","물론 성경은 모세가 이 순간 자신의 과거를 어떻게 회상했는지 말해 주지 않는다. 그러나 두 사건을 나란히 읽는 독자는 이전의 개입과 지금의 파송이 서로 다르다는 사실을 발견하게 된다.","이제 모세는 자신의 계획이 아니라 하나님의 말씀을 듣고 있다.","하지만 하나님의 명령을 들었다고 해서 모세가 곧바로 자신 있게 나선 것은 아니었다.","“내가 누구이기에” (11–12절)","모세는 하나님께 묻는다.","“내가 누구이기에 바로에게 가며 이스라엘 자손을 애굽에서 인도하여 내리이까?”","이 물음은 모세가 자신에게 맡겨진 일이 얼마나 큰지를 알고 있음을 드러낸다.","바로는 애굽의 왕이다. 이스라엘은 오랜 압제 아래 있는 백성이다. 그리고 모세는 지금 미디안에서 양 떼를 돌보고 있다.","그가 맡아야 할 일과 그 자신의 형편 사이에는 커다란 거리가 있다.","모세는 바로 그 거리를 질문한다.","“내가 누구이기에.”","그런데 하나님은 모세가 어떤 능력을 가지고 있는지, 앞으로 얼마나 훌륭한 지도자가 될 것인지 설명하지 않으신다.","하나님은 이렇게 말씀하신다.","“내가 반드시 너와 함께 있으리라.”","히브리어로는 *에흐예 임마크*(אֶהְיֶה עִמָּךְ)이다.","여기서 가장 중요한 것은 모세가 어떤 사람인가에 대한 평가가 아니라 하나님이 그와 함께하시겠다는 약속이다.","모세는 자신의 자격을 묻는다. 하나님은 자신의 동행을 약속하신다.","모세의 질문과 하나님의 대답이 정확히 같은 종류의 설명은 아니다. 그래서 오히려 하나님의 응답은 더 깊은 의미를 지닌다. 하나님은 사명의 근거를 모세 자신에게서 찾도록 하지 않으시고, 그를 보내시는 하나님의 임재에 두신다.","그리고 하나님은 한 가지 표징을 약속하신다.","이스라엘 백성을 애굽에서 이끌어 낸 뒤 그들이 이 산에서 하나님을 섬기게 될 것이라는 약속이다.","그 표징은 지금 당장 모세가 모든 일을 확인할 수 있게 해 주는 증거가 아니다. 구원의 여정이 이루어진 뒤에야 온전히 드러날 미래의 사건을 가리킨다.","지금 모세가 서 있는 산에서 장차 이스라엘 백성이 하나님을 섬기게 될 것이다.","처음에 모세는 혼자 양 떼를 이끌고 이 산에 왔다. 그러나 하나님이 약속하시는 미래에는 애굽에서 해방된 백성이 이 산에서 하나님 앞에 서게 된다.","한 사람을 향한 부르심이 한 백성의 구원과 예배를 향해 열리고 있는 것이다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"relatedResearch":[],"readerSources":[]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"EXODUS_03_13_22_READABLE_WORBS_v0.1_CANDIDATE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/EXODUS_03_13_22_READABLE_WORBS_v0.1_CANDIDATE.md","sourceSha256":"9dee75920e52017cbadba3b6888833d808a362f6f89446ff7842eda67c55dccc","passage":{"book":"exo","chapter":3,"v1":13,"v2":22,"ref":"출애굽기 3:13–22"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"이름을 물은 모세에게 하나님이 들려주신 것","overview":["모세는 자신이 누구인지 묻던 데서 한 걸음 더 나아가, 백성이 하나님이 누구냐고 물으면 어떻게 답해야 할지를 묻는다. 하나님은 ‘나는 스스로 있는 자’라는 깊은 말씀을 주시면서도 조상들의 하나님이라는 오래된 약속을 다시 일깨우신다. 그 이름은 비밀스러운 힘을 얻는 주문이 아니라 고통을 보고 계시며 백성을 인도하실 분이 누구신지를 드러낸다. 모세가 전해야 할 것은 단순한 이름이 아니라 하나님이 기억하시고 이루실 구원의 약속이다."],"centralMessage":"모세는 자신이 누구인지 묻던 데서 한 걸음 더 나아가, 백성이 하나님이 누구냐고 물으면 어떻게 답해야 할지를 묻는다. 하나님은 ‘나는 스스로 있는 자’라는 깊은 말씀을 주시면서도 조상들의 하나님이라는 오래된 약속을 다시 일깨우신다. 그 이름은 비밀스러운 힘을 얻는 주문이 아니라 고통을 보고 계시며 백성을 인도하실 분이 누구신지를 드러낸다. 모세가 전해야 할 것은 단순한 이름이 아니라 하나님이 기억하시고 이루실 구원의 약속이다.","literaryStructure":[{"v1":13,"v2":15,"title":"모세가 알고 싶었던 하나님의 이름"},{"v1":16,"v2":18,"title":"이름과 함께 기억되는 조상들의 약속"},{"v1":19,"v2":22,"title":"거절을 아시면서도 보내시는 하나님"}],"sections":[{"id":"exo3-13-15","v1":13,"v2":15,"title":"모세가 알고 싶었던 하나님의 이름","paragraphs":["하나님은 모세에게 애굽으로 가라고 하셨다. 모세는 ‘내가 누구이기에’ 바로에게 가겠느냐고 물었고, 하나님은 함께하시겠다고 답하셨다. 이제 모세에게 또 하나의 질문이 생긴다. 이스라엘 자손에게 조상들의 하나님이 자신을 보내셨다고 말할 때 그들이 그 하나님의 이름이 무엇이냐고 물으면 어떻게 하겠느냐는 것이다. 모세는 아직 백성에게 가지 않았다. 그가 펼쳐 보이는 상황은 앞으로 마주할 수 있는 질문이다. 본문은 모세가 벌써 백성에게 거절당했다고 말하지 않는다. 그에게 필요한 것은 자신의 사명을 설명할 수 있는 말이다.","하나님의 대답은 짧고도 깊다. “나는 스스로 있는 자이니라.” 히브리어 에흐예 아쉐르 에흐예(אֶהְיֶה אֲשֶׁר אֶהְיֶה)는 ‘나는 나인 자다’ 또는 ‘나는 내가 있을 자로 있을 것이다’라는 가능성을 함께 생각하게 하는 표현이다. 동사 하야의 1인칭 형태 에흐예는 바로 앞 12절의 “내가 너와 함께 있으리라”에도 등장한다. 하나님이 모세에게 들려주신 자기 이름의 말씀은 그가 모세와 함께하겠다고 하신 약속에서 멀리 떨어진 추상적인 수수께끼만은 아니다. 하나님은 어느 사람이 만들어 주는 신분이나 능력으로 존재하시는 분이 아니라 자기 자신으로 존재하시며 자신의 약속을 이루시는 분이다. 이 문구에 대한 철학적 해석은 오래 이어져 왔지만, 출애굽기 안에서 먼저 들려오는 것은 모세를 보내시는 하나님의 살아 있는 현존과 신실함이다.","이어 15절에서 하나님은 자신을 아브라함과 이삭과 야곱의 하나님, 여호와라고 밝히시고 이것이 대대로 기억할 이름이라고 하신다. 14절의 ‘에흐예’와 15절의 신명 YHWH의 어원·발음 관계를 하나의 단순한 공식으로 확정해서는 안 된다. 후대 유대교 전통에서는 네 자음으로 기록된 이름을 그대로 발음하기보다 ‘주님’에 해당하는 표현으로 읽었다. 오늘날 널리 쓰이는 ‘야훼’도 고대 발음을 완벽하게 복원했다고 보기는 어렵다. 독자는 이 이름의 음절을 정확하게 말할 때 신적 힘을 얻게 된다고 이해해서는 안 된다. 이 이름으로 자신을 밝히신 하나님이 누구이며 어떻게 행하시는지가 이어지는 말씀의 중심이다."]},{"id":"exo3-16-18","v1":16,"v2":18,"title":"이름과 함께 기억되는 조상들의 약속","paragraphs":["하나님은 모세에게 이스라엘의 장로들을 모으라고 하신다. 홀로 바로에게 달려가 자신의 능력을 증명하라는 명령부터 주신 것이 아니다. 먼저 자기 백성에게 조상들의 하나님이 자신에게 나타나셨다는 사실을 전하라고 하신다. 하나님은 그들의 고통을 분명히 살피셨고 애굽에서 겪는 일들을 아신다. 16절의 ‘돌보았다/살폈다’에 해당하는 파카드(פקד)는 단순히 사람을 방문했다는 말로 좁히기 어렵다. 하나님이 주의를 기울여 자신의 백성을 위해 행동하시려는 맥락에서 쓰인다. 본문은 강조 형태로 이 돌보심의 확실성을 울린다.","하나님은 다시 좋은 땅, 젖과 꿀이 흐르는 땅으로 인도하시겠다고 약속하신다. 약속이 3:8에서 이미 나왔는데도 다시 들리는 이유가 있다. 모세가 말해야 할 소식은 놀라운 이름 하나가 아니라 조상들에게 약속하신 하나님이 지금도 그 백성의 고통을 외면하지 않으신다는 사실이다. 장로들이 모세의 말을 들으리라는 18절의 말씀은 앞으로 펼쳐질 어려움이 모두 사라진다는 뜻이 아니다. 모세가 자신에게 주어진 말씀을 들고 백성에게 돌아갈 수 있는 근거가 된다.","그다음 장로들과 함께 애굽 왕에게 가서 광야로 사흘 길을 가 하나님께 제사를 드리게 해 달라고 말하라는 지시가 이어진다. 처음 독자는 이것이 완전한 탈출 계획보다 작게 들릴 수 있다. 그러나 출애굽의 목적이 단순히 애굽의 노동에서 벗어나는 일로만 끝나지 않고 하나님을 예배하며 그분의 백성으로 살아가는 데 있다는 사실을 떠올리면 이 요구의 중요성이 보인다. 그렇다고 본문이 앞으로의 모든 협상 과정을 미리 자세히 설명하는 것은 아니다."]},{"id":"exo3-19-22","v1":19,"v2":22,"title":"거절을 아시면서도 보내시는 하나님","paragraphs":["하나님은 바로가 쉽게 허락하지 않을 것이라고 먼저 말씀하신다. 모세가 백성에게 돌아가고 장로들이 그 말을 듣는다고 해서 곧바로 길이 열리는 것은 아니다. 애굽 왕은 강한 손의 개입이 있기 전에는 보내지 않으리라는 것이다. 하나님은 모세에게 곧 닥칠 거절을 숨기지 않으신다. 그 대신 애굽 가운데 이적을 행하시고, 마침내 왕이 이스라엘을 보내게 될 것이라고 밝히신다. 애굽에서 벌어질 긴 갈등의 문이 여기서 열린다.","더 놀라운 예고도 있다. 백성은 빈손으로 떠나지 않을 것이다. 하나님은 애굽 사람들에게 은과 금과 의복을 얻어 나올 일을 말씀하신다. 이는 오랫동안 노역에 시달리던 백성이 굴욕적인 빈손으로만 떠나지 않을 것임을 보여 준다. 다만 이것을 오늘날의 사적인 재산 획득 원리로 곧장 적용해서는 안 된다. 이 대목은 창세기 15:14의 약속, 곧 압제하던 나라를 심판한 뒤 백성이 큰 재물을 이끌고 나올 것이라는 말씀과 이어진다. 후에 일어날 일들이 구체적으로 어떤 방식으로 성취될지는 이어지는 출애굽 서사가 들려줄 것이다.","모세는 자신의 이름이 아니라 자신을 보내시는 분의 이름을 묻고 있었다. 하나님은 그에게 한 단어만 전하고 침묵하지 않으셨다. 조상들과 맺은 약속을 기억하시고 고난을 아시며, 왕의 저항까지 알고 계시는 하나님이 어떤 일을 하실지 들려주셨다. 성경이 말하는 하나님의 이름은 이 말씀들을 떼어 낸 빈 표지가 아니다. 그분의 신실하심과 구원의 행위가 그 이름을 알아가게 한다."]}],"lexicalCards":[{"verse":14,"lemma":"הָיָה","form":"אֶהְיֶה אֲשֶׁר אֶהְיֶה","pronunciation":"에흐예 아쉐르 에흐예","gloss":"나는 나인 자다 / 나는 내가 있을 자로 있을 것이다 — 문맥상 존재와 동행·신실함을 함께 고려해야 한다"},{"verse":15,"lemma":"יהוה","form":"יהוה","pronunciation":"야훼(재구성 발음)","gloss":"조상들의 하나님을 가리키는 네 자음의 신명; 고대 정확한 발음은 확정할 수 없다"},{"verse":16,"lemma":"פָּקַד","form":"פָּקֹד פָּקַדְתִּי","pronunciation":"파코드 파카드티","gloss":"내가 반드시 살폈다 — 부정사 절대형에 의한 강조와 구원의 주목"},{"verse":18,"lemma":"שָׁמַע","form":"וְשָׁמְעוּ","pronunciation":"베샤메우","gloss":"그들이 들을 것이다 — 이 문맥에서는 장로들이 모세의 말을 받아들임"}],"discoveries":[{"id":"exo3-13-15-disc","title":"모세가 알고 싶었던 하나님의 이름","paragraphs":["하나님은 모세에게 애굽으로 가라고 하셨다. 모세는 ‘내가 누구이기에’ 바로에게 가겠느냐고 물었고, 하나님은 함께하시겠다고 답하셨다. 이제 모세에게 또 하나의 질문이 생긴다. 이스라엘 자손에게 조상들의 하나님이 자신을 보내셨다고 말할 때 그들이 그 하나님의 이름이 무엇이냐고 물으면 어떻게 하겠느냐는 것이다. 모세는 아직 백성에게 가지 않았다. 그가 펼쳐 보이는 상황은 앞으로 마주할 수 있는 질문이다. 본문은 모세가 벌써 백성에게 거절당했다고 말하지 않는다. 그에게 필요한 것은 자신의 사명을 설명할 수 있는 말이다."]},{"id":"exo3-16-18-disc","title":"이름과 함께 기억되는 조상들의 약속","paragraphs":["하나님은 모세에게 이스라엘의 장로들을 모으라고 하신다. 홀로 바로에게 달려가 자신의 능력을 증명하라는 명령부터 주신 것이 아니다. 먼저 자기 백성에게 조상들의 하나님이 자신에게 나타나셨다는 사실을 전하라고 하신다. 하나님은 그들의 고통을 분명히 살피셨고 애굽에서 겪는 일들을 아신다. 16절의 ‘돌보았다/살폈다’에 해당하는 파카드(פקד)는 단순히 사람을 방문했다는 말로 좁히기 어렵다. 하나님이 주의를 기울여 자신의 백성을 위해 행동하시려는 맥락에서 쓰인다. 본문은 강조 형태로 이 돌보심의 확실성을 울린다."]},{"id":"exo3-19-22-disc","title":"거절을 아시면서도 보내시는 하나님","paragraphs":["하나님은 바로가 쉽게 허락하지 않을 것이라고 먼저 말씀하신다. 모세가 백성에게 돌아가고 장로들이 그 말을 듣는다고 해서 곧바로 길이 열리는 것은 아니다. 애굽 왕은 강한 손의 개입이 있기 전에는 보내지 않으리라는 것이다. 하나님은 모세에게 곧 닥칠 거절을 숨기지 않으신다. 그 대신 애굽 가운데 이적을 행하시고, 마침내 왕이 이스라엘을 보내게 될 것이라고 밝히신다. 애굽에서 벌어질 긴 갈등의 문이 여기서 열린다."]}],"canonicalLinks":[{"ref":"출애굽기 3:12","note":"동행 약속의 에흐예와 3:14 자기 계시가 연속된다"},{"ref":"출애굽기 6:2–8","note":"조상들의 하나님과 이름, 언약, 구출이 재강조된다"},{"ref":"창세기 15:13–14","note":"압제 후 구출과 재물을 얻는 약속"},{"ref":"출애굽기 12:35–36","note":"애굽 사람들로부터 물품을 얻어 나오는 후속 서사"}],"theologicalSynthesis":["‘에흐예 아쉐르 에흐예’의 시제와 번역에는 해석의 여지가 있다. ‘스스로 있는 자’라는 익숙한 번역을 존중하면서도 3:12의 동행 약속과 3:14의 표현을 나란히 살핀다. 신명 YHWH의 정확한 고대 발음은 단정하지 않는다. 3:18의 사흘 길 요청은 역사적 협상 문맥과 예배라는 목적을 함께 고려하되 모세가 공개적으로 말하지 않은 모든 계획을 상상하여 덧붙이지 않는다. 3:21–22의 재물을 받아 나오는 일은 창 15:14 및 출 12:35–36과 연결되며, 현대의 일반적 재산 윤리를 위한 직접 규칙은 아니다."],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"StudyNotes.xml Exod.3.13-22","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"tn_EXO.tsv 3:13-22","license":"CC BY-SA 4.0"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"EXODUS_04_01_31_READABLE_WORBS_v0.1_CANDIDATE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/EXODUS_04_01_31_READABLE_WORBS_v0.1_CANDIDATE.md","sourceSha256":"cd43a6a5d9754ff4a9f26f88097081db8d2b799e26d8e203eb740feff1d94865","passage":{"book":"exo","chapter":4,"v1":1,"v2":31,"ref":"출애굽기 4:1–31"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"지팡이를 든 사람이 애굽으로 돌아가다","overview":["모세는 하나님의 이름을 들었지만 여전히 두렵고 망설인다. 백성이 자신을 믿지 않을까 걱정하고, 자신의 말솜씨가 부족하다고 호소하다가 마침내 다른 사람을 보내시라고까지 청한다. 하나님은 표징을 주시고 입을 만드신 분으로서 도우시겠다고 말씀하시며, 아론을 동역자로 세워 주신다. 애굽으로 돌아가는 길에는 설명하기 어려운 위기가 찾아오지만, 마침내 모세와 아론이 만나고 장로들 앞에서 하나님의 말씀을 전한다. 백성은 하나님이 자신들의 고난을 돌아보셨다는 소식을 듣고 머리 숙여 경배한다."],"centralMessage":"모세는 하나님의 이름을 들었지만 여전히 두렵고 망설인다. 백성이 자신을 믿지 않을까 걱정하고, 자신의 말솜씨가 부족하다고 호소하다가 마침내 다른 사람을 보내시라고까지 청한다. 하나님은 표징을 주시고 입을 만드신 분으로서 도우시겠다고 말씀하시며, 아론을 동역자로 세워 주신다. 애굽으로 돌아가는 길에는 설명하기 어려운 위기가 찾아오지만, 마침내 모세와 아론이 만나고 장로들 앞에서 하나님의 말씀을 전한다. 백성은 하나님이 자신들의 고난을 돌아보셨다는 소식을 듣고 머리 숙여 경배한다.","literaryStructure":[{"v1":1,"v2":9,"title":"나를 믿지 않으면 어떻게 하겠습니까"},{"v1":10,"v2":17,"title":"입이 둔한 사람을 보내시는 하나님"},{"v1":18,"v2":23,"title":"돌아가는 길에 들려온 경고"},{"v1":24,"v2":26,"title":"길 위의 이해하기 어려운 밤"},{"v1":27,"v2":31,"title":"형제를 만나고 백성이 머리 숙이다"}],"sections":[{"id":"exo4-1-9","v1":1,"v2":9,"title":"나를 믿지 않으면 어떻게 하겠습니까","paragraphs":["하나님은 모세에게 장로들이 그의 말을 들을 것이라고 말씀하셨다. 하지만 모세는 또 묻는다. 사람들이 자기 말을 믿지 않고, 하나님이 나타나셨다는 증언을 받아들이지 않으면 어떻게 하느냐는 것이다. 이 질문은 단지 악의적인 불순종이라는 한마디로 정리하기 어렵다. 과거 동족을 도우려다가 ‘누가 너를 세웠느냐’라는 말을 듣고 떠나야 했던 모세가 이제 하나님이 자신을 보내셨다는 말을 전해야 한다. 다만 본문은 그의 옛 기억이 바로 이 질문을 일으켰다고 명시하지 않으므로, 두 장면의 연결은 문학적 울림으로 남겨야 한다.","하나님은 먼저 모세의 손에 무엇이 있는지 물으신다. “지팡이니이다.” 목자의 손에 있던 평범한 지팡이를 땅에 던지자 뱀이 되고, 모세는 놀라 피한다. 하나님이 꼬리를 잡으라고 하시자 다시 지팡이가 된다. 이 첫 표징은 모세가 자신의 손에 익숙했던 도구조차 하나님 말씀 앞에서 새롭게 경험하게 한다. 뱀은 고대의 상징 세계에서 특별한 의미를 가질 수 있지만, 이 짧은 장면만으로 애굽의 왕권 표상을 직접 전복하는 의식이었다고 단정할 필요는 없다. 본문은 표징의 목적을 분명히 말한다. 조상들의 하나님이 모세에게 나타나셨음을 백성이 믿게 하려는 것이다.","이어 모세가 품에 손을 넣었다 꺼내자 피부에 심한 병변이 나타나고, 다시 넣었다 꺼내자 회복된다. 히브리어로 흔히 ‘나병’이라 옮기던 차라아트는 현대 의학의 한센병과 정확히 같은 질환만을 지칭하지 않는다. 본문이 보여 주는 것은 모세가 자기 힘으로 만들거나 고칠 수 없는 변화가 하나님 말씀에 따라 일어난다는 점이다. 마지막으로 하나님은 나일강 물을 떠서 마른땅에 부으면 피가 될 것이라고 말씀하신다. 이 셋째 표징은 아직 이 자리에서 실행되었다고 서술되지 않는다. 만약 백성이 앞선 두 표징을 믿지 않을 경우를 위한 약속으로 제시된다. 애굽을 살리는 나일강의 물이 피로 바뀌는 예고는 뒤에 펼쳐질 재앙 이야기와도 연결된다."]},{"id":"exo4-10-17","v1":10,"v2":17,"title":"입이 둔한 사람을 보내시는 하나님","paragraphs":["모세의 다음 걱정은 말이다. 그는 자신이 본래 말을 잘하지 못하며, 하나님이 말씀하신 뒤에도 입과 혀가 둔하다고 호소한다. 이 표현은 말하는 능력에 관한 실제 어려움을 전하지만, 현대 의학의 특정 언어 장애를 진단할 근거까지 제공하지는 않는다. 하나님은 “누가 사람의 입을 지었느냐”라고 되물으신다. 창조주이신 하나님은 사람이 말하고 듣고 보는 능력의 근원이시다. 그리고 “내가 네 입과 함께 있어서 할 말을 가르치리라”고 약속하신다. 앞서 3:12에서 모세 자신과 함께하겠다고 하신 말씀이 이번에는 그의 입과 말하는 일에까지 이어진다.","그러나 모세는 마침내 “보낼 만한 자를 보내소서”라고 말한다. 문맥상 다른 사람을 보내 달라는 요청이다. 지금까지의 질문이 하나씩 해결되었어도 그는 여전히 그 사명을 피하고 싶어 한다. 이때 여호와께서 노하셨다고 성경은 분명하게 밝힌다. 하나님의 인내와 모세의 망설임을 설명한다고 해서 이 진노를 지워서는 안 된다. 동시에 하나님은 아론이라는 구체적인 도움을 주신다. 레위 사람 아론은 말을 잘하며, 모세를 만나 기뻐할 것이라고 하신다. 모세가 하나님의 말씀을 아론에게 전하고 아론이 그것을 백성에게 말하게 된다. '그는 네 입이 될 것이요 너는 그에게 하나님 같이 되리라'는 표현은 모세가 신적 존재가 된다는 선언이 아니라 전달되는 말과 권위의 관계를 설명하는 비유다.","하나님은 지팡이를 손에 잡고 그것으로 표징을 행하라고 다시 말씀하신다. 이제 목자가 되돌아가야 할 길에는 말, 동행할 사람, 손에 잡을 도구가 주어져 있다. 하지만 출애굽기는 이것을 모세의 모든 두려움이 깨끗이 사라졌다는 이야기는 하지 않는다. 부르심에 대한 반문을 지나 하나님의 말씀을 따라 출발하는 움직임이 다음 장면을 연다."]},{"id":"exo4-18-23","v1":18,"v2":23,"title":"돌아가는 길에 들려온 경고","paragraphs":["모세는 장인 이드로에게 돌아가 형제들이 살아 있는지 살피러 애굽에 다녀오겠다고 말한다. 이드로는 평안히 가라고 허락한다. 하나님은 미디안에서 모세에게 그를 죽이려던 사람들이 모두 죽었다고 알려 주신다. 이제 모세는 아내와 아들들을 데리고 애굽으로 향한다. 그의 손에는 ‘하나님의 지팡이’가 들려 있다. 이전에는 양을 몰던 도구였지만, 하나님이 표징을 행하라고 명하신 뒤에는 그분의 구원 행동과 연결되는 물건이 되었다. 본문이 모세가 어떤 시간표로 미디안을 떠났는지 모든 세부를 밝혀 주는 것은 아니다.","하나님은 바로 앞에서 표징을 행하라고 하시면서도 왕이 쉽게 백성을 보내지 않을 것을 다시 알려 주신다. 바로의 마음이 완고해지는 문제는 이후 출애굽기 전체에 걸쳐 긴 논의를 부르는 주제다. 이 단락에서는 하나님이 바로의 저항을 미리 알고 계시며, 구원의 과정이 권력자의 호의만으로 이루어지지 않을 것이라는 점이 명확하다. 동시에 22절에서 이스라엘을 “내 아들, 내 장자”라고 부르신다. 이는 백성을 사랑하시고 특별한 관계로 삼으신다는 언약적 표현이다. 바로는 이스라엘을 노역의 수단으로 삼았지만 하나님은 자기 아들을 섬기도록 내보내라고 요구하신다. 이어 바로가 거절하면 그의 장자를 치시겠다는 무거운 경고가 나온다. 이 대조는 마지막 재앙의 방향을 미리 보여 준다."]},{"id":"exo4-24-26","v1":24,"v2":26,"title":"길 위의 이해하기 어려운 밤","paragraphs":["바로에게 돌아가는 여정 중 숙소에서 뜻밖의 일이 벌어진다. 여호와께서 그를 만나 죽이려 하셨다는 것이다. 바로를 대면하라는 부르심을 받고 출발한 모세에게 왜 이런 위협이 찾아오는지 이야기는 자세히 설명하지 않는다. '그'가 모세를 가리키는지 아들을 가리키는지, 어떤 배경 사건이 있었는지 학자들 사이에도 논의가 있다. 가장 흔한 해석은 모세를 가리킨다는 것이지만 본문만으로 모든 모호함을 지웠다고 할 수 없다.","십보라는 돌칼로 아들의 포피를 베고 그것을 발에 대며 “당신은 참으로 내게 피 남편이로다”라고 말한다. 이후 여호와께서 그를 놓아주셨다는 문장이 이어진다. 할례는 창세기 17장에서 아브라함의 언약과 연결되는 표지다. 따라서 언약 공동체의 지도자로 보내지는 모세의 집안에서 이 표지가 문제가 되었다고 이해하는 견해는 설득력이 있다. 그러나 십보라가 어떤 생각으로 이 말을 했는지, “발”이 정확히 누구의 어디를 가리키는지, '피 남편'이라는 말이 어떤 관습에서 비롯되었는지를 확정할 수는 없다. 설명되지 않는 곳을 극적인 상상으로 채우지 않는 것이 오히려 이 장면의 긴장을 보존한다. 분명한 것은 이야기에서 십보라의 행동 뒤 위기가 끝난다는 사실이다. 다른 사람에게 말씀을 전할 이의 가정도 언약의 요구와 무관하게 다뤄질 수 없다는 해석은 가능하지만, 성경이 모든 의도를 직접 해설해 주는 것은 아니다."]},{"id":"exo4-27-31","v1":27,"v2":31,"title":"형제를 만나고 백성이 머리 숙이다","paragraphs":["하나님은 아론에게 광야로 가서 모세를 만나라고 말씀하신다. 아론은 하나님의 산에서 모세를 만나 입을 맞춘다. 떨기나무에서 모세에게 약속하셨던 동역자가 실제로 길 위에 나타난 것이다. 두 사람은 함께 움직인다. 모세가 여호와께서 자신에게 명령하신 말씀과 표징을 아론에게 전하고, 그들은 이스라엘 장로들을 모은다. 아론이 말씀을 전하고 표징이 백성 앞에서 이루어진다. 30절에서 표징을 구체적으로 누가 모두 실행했는지의 대명사 지시에는 번역상의 논의가 있으므로 한 사람의 역할만 지나치게 확정할 필요는 없다.","그리고 백성은 믿었다. 하나님이 이스라엘을 돌아보시고 그들의 고난을 살피셨다는 말을 듣자 머리 숙여 경배한다. 출애굽기 2장 끝에서 들렸던 신음, 3장에서 하나님이 보았고 들었다고 하신 말씀, 4장에서 모세에게 전하라고 하신 약속이 마침내 공동체의 응답으로 이어진다. 그렇다고 이 첫 믿음이 앞으로 모든 시험을 흔들림 없이 통과하리라는 뜻은 아니다. 본문 뒤에는 바로의 거절과 더 심해질 노역, 원망과 두려움이 기다린다. 그러나 이 장의 마지막 장면은 그 미래의 어려움을 먼저 끌어와 흐리게 할 필요가 없다. 고통이 끝나지 않은 그 자리에서도 백성은 하나님이 자신들을 기억하고 찾아오셨다는 소식을 듣고 예배한다."]}],"lexicalCards":[{"verse":1,"lemma":"אָמַן","form":"יַאֲמִינוּ","pronunciation":"야아미누","gloss":"그들이 믿을 것이다 — 하나님의 현현에 대한 모세의 증언을 받아들이는 문제"},{"verse":6,"lemma":"צָרַעַת","form":"מְצֹרַעַת","pronunciation":"메초라아트","gloss":"피부 질환에 걸린 상태; 현대 한센병으로 동일시하지 않는다"},{"verse":10,"lemma":"כָּבֵד","form":"כְבַד־פֶּה וּכְבַד לָשׁוֹן","pronunciation":"케바드 페 우케바드 라숀","gloss":"입과 혀가 무겁다 — 말하기의 어려움에 대한 모세의 표현"},{"verse":14,"lemma":"חָרָה","form":"וַיִּחַר־אַף","pronunciation":"바이하르 아프","gloss":"진노가 타올랐다 — 모세의 회피에 대한 여호와의 명시된 반응"},{"verse":22,"lemma":"בְּכוֹר","form":"בְּנִי בְכֹרִי","pronunciation":"베니 베코리","gloss":"내 아들, 내 장자 — 이스라엘과 하나님의 특별한 관계를 가리킴"},{"verse":31,"lemma":"פָּקַד","form":"פָקַד","pronunciation":"파카드","gloss":"돌보셨다 — 하나님이 백성의 고통을 살피고 행동하심"}],"discoveries":[{"id":"exo4-1-9-disc","title":"나를 믿지 않으면 어떻게 하겠습니까","paragraphs":["하나님은 모세에게 장로들이 그의 말을 들을 것이라고 말씀하셨다. 하지만 모세는 또 묻는다. 사람들이 자기 말을 믿지 않고, 하나님이 나타나셨다는 증언을 받아들이지 않으면 어떻게 하느냐는 것이다. 이 질문은 단지 악의적인 불순종이라는 한마디로 정리하기 어렵다. 과거 동족을 도우려다가 ‘누가 너를 세웠느냐’라는 말을 듣고 떠나야 했던 모세가 이제 하나님이 자신을 보내셨다는 말을 전해야 한다. 다만 본문은 그의 옛 기억이 바로 이 질문을 일으켰다고 명시하지 않으므로, 두 장면의 연결은 문학적 울림으로 남겨야 한다."]},{"id":"exo4-10-17-disc","title":"입이 둔한 사람을 보내시는 하나님","paragraphs":["모세의 다음 걱정은 말이다. 그는 자신이 본래 말을 잘하지 못하며, 하나님이 말씀하신 뒤에도 입과 혀가 둔하다고 호소한다. 이 표현은 말하는 능력에 관한 실제 어려움을 전하지만, 현대 의학의 특정 언어 장애를 진단할 근거까지 제공하지는 않는다. 하나님은 “누가 사람의 입을 지었느냐”라고 되물으신다. 창조주이신 하나님은 사람이 말하고 듣고 보는 능력의 근원이시다. 그리고 “내가 네 입과 함께 있어서 할 말을 가르치리라”고 약속하신다. 앞서 3:12에서 모세 자신과 함께하겠다고 하신 말씀이 이번에는 그의 입과 말하는 일에까지 이어진다."]},{"id":"exo4-18-23-disc","title":"돌아가는 길에 들려온 경고","paragraphs":["모세는 장인 이드로에게 돌아가 형제들이 살아 있는지 살피러 애굽에 다녀오겠다고 말한다. 이드로는 평안히 가라고 허락한다. 하나님은 미디안에서 모세에게 그를 죽이려던 사람들이 모두 죽었다고 알려 주신다. 이제 모세는 아내와 아들들을 데리고 애굽으로 향한다. 그의 손에는 ‘하나님의 지팡이’가 들려 있다. 이전에는 양을 몰던 도구였지만, 하나님이 표징을 행하라고 명하신 뒤에는 그분의 구원 행동과 연결되는 물건이 되었다. 본문이 모세가 어떤 시간표로 미디안을 떠났는지 모든 세부를 밝혀 주는 것은 아니다."]},{"id":"exo4-24-26-disc","title":"길 위의 이해하기 어려운 밤","paragraphs":["바로에게 돌아가는 여정 중 숙소에서 뜻밖의 일이 벌어진다. 여호와께서 그를 만나 죽이려 하셨다는 것이다. 바로를 대면하라는 부르심을 받고 출발한 모세에게 왜 이런 위협이 찾아오는지 이야기는 자세히 설명하지 않는다. '그'가 모세를 가리키는지 아들을 가리키는지, 어떤 배경 사건이 있었는지 학자들 사이에도 논의가 있다. 가장 흔한 해석은 모세를 가리킨다는 것이지만 본문만으로 모든 모호함을 지웠다고 할 수 없다."]},{"id":"exo4-27-31-disc","title":"형제를 만나고 백성이 머리 숙이다","paragraphs":["하나님은 아론에게 광야로 가서 모세를 만나라고 말씀하신다. 아론은 하나님의 산에서 모세를 만나 입을 맞춘다. 떨기나무에서 모세에게 약속하셨던 동역자가 실제로 길 위에 나타난 것이다. 두 사람은 함께 움직인다. 모세가 여호와께서 자신에게 명령하신 말씀과 표징을 아론에게 전하고, 그들은 이스라엘 장로들을 모은다. 아론이 말씀을 전하고 표징이 백성 앞에서 이루어진다. 30절에서 표징을 구체적으로 누가 모두 실행했는지의 대명사 지시에는 번역상의 논의가 있으므로 한 사람의 역할만 지나치게 확정할 필요는 없다."]}],"canonicalLinks":[{"ref":"출애굽기 2:14","note":"모세의 과거 거절과 새 소명의 문학적 긴장"},{"ref":"출애굽기 3:11–12","note":"하나님의 동행 약속이 말하는 일에까지 이어진다"},{"ref":"창세기 17:9–14","note":"할례와 언약의 표지"},{"ref":"출애굽기 11–12장","note":"바로의 장자와 이스라엘 장자 경고의 후속 전개"},{"ref":"출애굽기 18:2–4","note":"모세 가족과 아들들에 관한 후속 정보"}],"theologicalSynthesis":["모세의 반문은 3:11의 자격, 3:13의 이름, 4:1의 신뢰, 4:10의 말하기, 4:13의 회피로 이어진다. 다만 이를 모두 같은 심리 상태로 단순화해서는 안 된다. 표징 세 가지는 지팡이와 뱀, 손의 피부 변화와 회복, 나일강 물과 피이며 셋째 표징은 명령과 예고로 제시된다. 차라아트를 한센병으로 단정하지 않는다. 4:24–26의 대명사와 관습적 표현, 할례의 의미는 확정된 본문 사실과 해석을 구별한다. 4:22의 ‘장자’와 4:23의 장자 심판은 후대의 열 번째 재앙 및 유월절 이야기와 연결된다."],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"StudyNotes.xml Exod.4.1-31","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"tn_EXO.tsv 4:1-31","license":"CC BY-SA 4.0"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"EXODUS_06_14_27_READABLE_WORBS_v0.1_CANDIDATE","sourcePath":"G:\\내 드라이브\\Jude_Lee_OS\\01_PROJECTS\\01_목회연구_WORBS_BICS\\WORKING_COMMENTARY66_20261011\\EXODUS_06_14_27_READABLE_WORBS_v0.1_CANDIDATE.md","sourceSha256":"a9bf4e633839e6b41a23b84dc986679b1d590c7c60b358aaa11f684dc7de4926","passage":{"book":"exo","chapter":6,"chapterEnd":6,"v1":14,"v2":27,"ref":"출애굽기 6:14–27"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"이름의 기록, 구출의 사명","overview":["급박한 구출 서사 한가운데 계보가 들어선다. 이 목록은 줄거리를 잠시 멈추게 하지만 이야기의 방향을 잃게 하지 않는다. 모세와 아론은 어느 날 갑자기 등장한 이름 없는 지도자가 아니다. 이스라엘의 가족과 세대에 속한 사람들이며, 바로 이들에게 하나님이 애굽에서 이스라엘을 인도하라고 명령하셨다. 계보의 목적은 모든 지파의 역사를 동일한 분량으로 설명하는 것이 아니라 모세와 아론이 구체적으로 누구인지 확인하면서 다시 바로 앞에 세우는 데 있다."],"centralMessage":"급박한 구출 서사 한가운데 계보가 들어선다. 이 목록은 줄거리를 잠시 멈추게 하지만 이야기의 방향을 잃게 하지 않는다. 모세와 아론은 어느 날 갑자기 등장한 이름 없는 지도자가 아니다. 이스라엘의 가족과 세대에 속한 사람들이며, 바로 이들에게 하나님이 애굽에서 이스라엘을 인도하라고 명령하셨다. 계보의 목적은 모든 지파의 역사를 동일한 분량으로 설명하는 것이 아니라 모세와 아론이 구체적으로 누구인지 확인하면서 다시 바로 앞에 세우는 데 있다.","literaryStructure":[{"v1":14,"v2":19,"title":"르우벤과 시므온을 지나 레위로"},{"v1":20,"v2":25,"title":"아므람에서 아론과 모세로"},{"v1":26,"v2":27,"title":"바로 그 아론과 모세"}],"sections":[{"id":"exo6-14-19","v1":14,"v2":19,"title":"르우벤과 시므온을 지나 레위로","paragraphs":["계보는 이스라엘의 장자 르우벤부터 출발한다. 르우벤의 아들들, 시므온의 아들들이 간략히 적힌 뒤 레위의 가족으로 옮겨간다. 이 순서는 갑자기 레위를 시작점으로 삼지 않고 야곱의 아들들 가운데 그의 자리를 보여 준다. 그러나 모든 지파를 끝까지 따라가지는 않는다. 레위에 이르러 인물과 세대에 관한 정보가 확대되는 것은 이야기의 관심이 레위 가문 안에서 나올 아론과 모세에게 있기 때문이다.","레위의 아들 게르손, 고핫, 므라리와 그들의 가문 이름이 기록된다. 이어 고핫의 아들 가운데 아므람, 이스할, 헤브론, 웃시엘이 등장한다. 서로 비슷한 이름이 여러 세대에 반복되는 고대 계보 문맥에서는 이름의 일치만으로 동일인임을 판단할 수 없다. 이 목록은 현대적 의미의 모든 세대가 빠짐없이 적힌 가족관계 등록부라는 전제를 요구하지 않는다. 이야기 안에서 중요하게 기능하는 가족 관계를 보여 주는 계보로 읽는 것이 출발점이다."]},{"id":"exo6-20-25","v1":20,"v2":25,"title":"아므람에서 아론과 모세로","paragraphs":["아므람은 아버지의 누이 요게벳을 아내로 맞고, 그에게서 아론과 모세가 태어난 것으로 기록된다. 이 결혼 관계를 읽을 때 후대 레위기의 친족혼 규정을 곧장 당시 가족의 심리와 사회적 평가에 소급할 필요는 없다. 출애굽기의 초점은 두 사람의 부모가 누구인지 알려 주는 데 있다. 이스할과 웃시엘의 후손들도 기록되며, 아론의 아내 엘리세바와 아들들, 엘르아살의 아내와 비느하스까지 이어진다.","목록을 읽는 독자는 모세만이 아니라 아론의 집안에 자세한 정보가 집중된다는 사실을 보게 된다. 후대 이스라엘의 제사장 가문을 이해하는 데 중요한 이름들이 이곳에 나타난다. 그렇다고 모든 인물이 지금부터 제사장 직무를 수행했다고 해석해서는 안 된다. 계보가 이후 공동체의 기억과 연결될 수 있다는 점과 이야기 시점에서 이미 수행한 직무를 구분할 필요가 있다."]},{"id":"exo6-26-27","v1":26,"v2":27,"title":"바로 그 아론과 모세","paragraphs":["계보 끝에서 이야기는 갑자기 처음의 명령으로 되돌아간다. 여호와께서 이스라엘 자손을 그 군대대로 애굽에서 인도하라고 말씀하신 대상이 바로 이 아론과 모세라는 것이다. 이어 이들이 바로에게 이스라엘을 보내라고 말한 바로 그 모세와 아론이라고 확인한다. 26절의 '아론과 모세'와 27절의 '모세와 아론'은 두 인물을 서로 다른 책임과 맥락에서 나란히 제시하며, 계보 목록과 바로 앞의 임무를 단단히 접합한다.","이 단락은 해방의 큰 사건이 이름 있는 사람들의 실제 가족사 속에서 진행된다고 말한다. 인간의 혈통 자체가 구원을 만들어 낸다는 선언은 아니다. 오히려 조상들에게 하신 하나님의 약속이 구체적인 세대와 사람에게 이어져 실현되는 모습이 계보 안에 놓여 있다. 다음 단락에서 모세의 말하기 어려움이 다시 등장할 때, 독자는 이 이름들과 가문을 지닌 두 사람이 바로 그 사명의 자리로 되돌아왔음을 이해하게 된다."]}],"lexicalCards":[],"discoveries":[{"id":"exo6-14-19-disc","title":"르우벤과 시므온을 지나 레위로","paragraphs":["계보는 이스라엘의 장자 르우벤부터 출발한다. 르우벤의 아들들, 시므온의 아들들이 간략히 적힌 뒤 레위의 가족으로 옮겨간다. 이 순서는 갑자기 레위를 시작점으로 삼지 않고 야곱의 아들들 가운데 그의 자리를 보여 준다. 그러나 모든 지파를 끝까지 따라가지는 않는다. 레위에 이르러 인물과 세대에 관한 정보가 확대되는 것은 이야기의 관심이 레위 가문 안에서 나올 아론과 모세에게 있기 때문이다."]},{"id":"exo6-20-25-disc","title":"아므람에서 아론과 모세로","paragraphs":["아므람은 아버지의 누이 요게벳을 아내로 맞고, 그에게서 아론과 모세가 태어난 것으로 기록된다. 이 결혼 관계를 읽을 때 후대 레위기의 친족혼 규정을 곧장 당시 가족의 심리와 사회적 평가에 소급할 필요는 없다. 출애굽기의 초점은 두 사람의 부모가 누구인지 알려 주는 데 있다. 이스할과 웃시엘의 후손들도 기록되며, 아론의 아내 엘리세바와 아들들, 엘르아살의 아내와 비느하스까지 이어진다."]},{"id":"exo6-26-27-disc","title":"바로 그 아론과 모세","paragraphs":["계보 끝에서 이야기는 갑자기 처음의 명령으로 되돌아간다. 여호와께서 이스라엘 자손을 그 군대대로 애굽에서 인도하라고 말씀하신 대상이 바로 이 아론과 모세라는 것이다. 이어 이들이 바로에게 이스라엘을 보내라고 말한 바로 그 모세와 아론이라고 확인한다. 26절의 '아론과 모세'와 27절의 '모세와 아론'은 두 인물을 서로 다른 책임과 맥락에서 나란히 제시하며, 계보 목록과 바로 앞의 임무를 단단히 접합한다."]}],"canonicalLinks":[{"ref":"창세기 46:8–11","note":"야곱 가족과 레위 이름의 이전 기록"},{"ref":"민수기 3:17–20","note":"레위 자손의 후속 공동체 구조"},{"ref":"출애굽기 6:10–13","note":"계보 직전 모세의 소명과 반문"}],"theologicalSynthesis":["창세기 46:8–11은 야곱 집안이 애굽에 내려갈 때의 르우벤·시므온·레위 이름을 전한다. 민수기 3:17–20은 레위 계열을 광야 공동체의 질서 안에서 다시 소개한다. 출애굽기 6:10–13과 6:28–7:7은 이 계보를 양쪽에서 감싸며 하나님이 누구를 바로에게 보내시는지를 알려 준다. 역대상 6장의 레위 후손 목록도 이 이름들의 후속 기억을 보여 주지만 세부 세대와 이름의 일치를 기계적으로 강제하지 않는다."],"relatedResearch":[],"readerSources":[{"name":"본문 직접 연구 초안","locator":"Exodus 6:14–6:27","license":"INTERNAL_CANDIDATE_ONLY"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"EXODUS_06_02_13_READABLE_WORBS_v0.1_CANDIDATE","sourcePath":"G:\\내 드라이브\\Jude_Lee_OS\\01_PROJECTS\\01_목회연구_WORBS_BICS\\WORKING_COMMENTARY66_20261011\\EXODUS_06_02_13_READABLE_WORBS_v0.1_CANDIDATE.md","sourceSha256":"5800b1edd1ebdb8deb8353b075806e16578de50ac50f6dda35281f3cc1180b9e","passage":{"book":"exo","chapter":6,"v1":2,"v2":13,"ref":"출애굽기 6:2–13"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"나는 여호와라, 약속을 다시 말씀하시는 하나님","overview":["모세가 바로를 처음 만난 뒤 상황은 더 나빠졌다. 벽돌을 만들어야 할 노동의 양은 줄지 않았고, 백성은 모세를 원망하였다. 하나님께서 보내셨는데 왜 고통이 커지는가. 출애굽기 5장 끝에서 모세가 던진 질문이 바로 이 자리의 배경이다. 하나님은 상황이 곧 좋아질 것이라는 막연한 격려 대신 자신이 누구인지, 조상들과 맺으신 약속이 무엇인지, 그리고 이제 무엇을 하실 것인지를 다시 말씀하신다. 본문의 중심은 모세의 확신이 아니라 여호와의 신실한 자기 선언에 있다."],"centralMessage":"모세가 바로를 처음 만난 뒤 상황은 더 나빠졌다. 벽돌을 만들어야 할 노동의 양은 줄지 않았고, 백성은 모세를 원망하였다. 하나님께서 보내셨는데 왜 고통이 커지는가. 출애굽기 5장 끝에서 모세가 던진 질문이 바로 이 자리의 배경이다. 하나님은 상황이 곧 좋아질 것이라는 막연한 격려 대신 자신이 누구인지, 조상들과 맺으신 약속이 무엇인지, 그리고 이제 무엇을 하실 것인지를 다시 말씀하신다. 본문의 중심은 모세의 확신이 아니라 여호와의 신실한 자기 선언에 있다.","literaryStructure":[{"v1":2,"v2":5,"title":"나는 여호와라"},{"v1":6,"v2":8,"title":"내가 너희를 인도하여 내리라"},{"v1":9,"v2":13,"title":"듣지 못하는 백성과 다시 보내심을 받은 모세"}],"sections":[{"id":"exo6-2-5","v1":2,"v2":5,"title":"나는 여호와라","paragraphs":["하나님의 첫마디는 '나는 여호와라'이다. 앞서 모세가 하나님의 이름을 들은 장면(3:13–15)을 기억하면, 여기서 하나님은 새로운 신의 이름을 처음 소개하는 것이 아니다. 처음부터 모세를 부르셨던 분이 바로 그분임을 다시 확인하시는 것이다. 구출의 기미가 보이지 않는 가운데 이름의 자기 선언이 앞에 놓인 까닭은 이스라엘이 겪고 있는 현실보다 하나님의 정체성이 약속의 기반이라는 데 있다.","3절에는 족장들에게 전능의 하나님으로 나타났으나 '나의 이름 여호와로는 그들에게 알리지 아니하였다'는 어려운 문장이 등장한다. 창세기에는 족장들이 여호와라는 이름을 아는 것으로 그려지는 대목이 있다(창 12:8; 26:25). 따라서 '이름의 문자적 발음이 전혀 알려지지 않았다'는 해석만으로는 두 본문의 관계가 간단히 해소되지 않는다. 출애굽기의 문맥에서 하나님이 이제 구원의 행동으로 그 이름이 담고 있는 신실함을 드러내신다는 해석은 중요하다. 동시에 이름 계시의 역사와 문학적 서술 관계는 실제 해석 쟁점으로 남겨야 한다.","하나님은 가나안 땅을 주시겠다는 언약과 애굽에서 신음하는 이스라엘의 소리를 함께 말씀하신다. '내가 기억하였노라'는 말은 하나님이 한동안 언약을 잊어버렸다가 생각해 냈다는 심리 묘사가 아니다. 이미 2:24에서 하나님이 언약을 기억하셨다는 서술이 나타났으며, 이제 그 기억이 구출의 행동으로 나타날 것을 예고한다. 애굽의 무거운 노역과 아브라함·이삭·야곱에게 주신 약속이 하나의 이야기로 연결된다."]},{"id":"exo6-6-8","v1":6,"v2":8,"title":"내가 너희를 인도하여 내리라","paragraphs":["하나님은 모세에게 이스라엘 자손에게 전할 말씀을 주신다. 이 단락에는 '내가'라는 주어를 중심으로 구원 행동의 동사들이 연속한다. 하나님이 노역에서 '빼내고', 종살이에서 '건지고', 편 팔과 큰 심판으로 '속량하며', 그들을 자신의 백성으로 '삼고', 그들의 하나님이 되고, 약속의 땅으로 '인도하여' 주실 것이라는 말씀이다. 구출은 단순한 장소 이동이 아니라 누구에게 속한 백성으로 살 것인가를 바꾸는 사건이다.","'속량하다'에 해당하는 히브리어 가알(גָּאַל, 가알)은 친족의 회복 책임과 관련된 용례를 갖는다. 그러나 이 문장에서 특정한 인간 친족법의 세부 조항을 그대로 옮겨 와야만 한다는 뜻은 아니다. 애굽의 권세 아래 있는 백성을 하나님이 자신의 권능으로 회복시키시는 행동을 강조한다. '편 팔'은 하나님이 신체를 가진 존재라는 묘사에 머물지 않고 왕권과 심판을 넘어서는 구원의 강력함을 표현한다.","'너희를 내 백성으로 삼고 나는 너희 하나님이 되리니'라는 문장은 출애굽 이야기의 심장이다. 여호와를 아는 일은 단순히 신명을 외우는 것이 아니라 애굽의 속박에서 자신을 건져 내신 분이 누구인지를 공동체의 경험으로 알아가는 일이다. 8절은 그 관계를 조상들에게 맹세하신 땅의 약속에 이어 붙인다. 하나님의 이름, 언약, 해방, 백성 됨, 땅이 한 흐름을 이룬다."]},{"id":"exo6-9-13","v1":9,"v2":13,"title":"듣지 못하는 백성과 다시 보내심을 받은 모세","paragraphs":["모세는 명령대로 말씀을 전하지만 이스라엘 자손은 듣지 않는다. 성경은 그 이유를 '마음의 상함과 가혹한 노역'에 둔다. 히브리어 미코체르 루아흐(מִקֹּצֶר רוּחַ, 미코체르 루아흐)는 문자적으로 '영/숨의 짧음에서'라는 표현으로, 숨 막히는 압박과 낙담의 상태를 묘사한다. 백성이 언약을 저버렸다는 판결을 이 문장에 덧씌우기보다, 극심한 고통 가운데 희망의 소식조차 받아들이기 어려운 현실을 읽어야 한다.","그런데 하나님은 모세를 바로에게 다시 보내신다. 모세의 반문은 자연스럽다. 자기 백성도 듣지 않는데 바로가 어떻게 듣겠느냐는 것이다. 모세는 자신을 '할례 받지 못한 입술'을 가진 사람이라고 표현한다(12절). 이는 4:10의 말하기 어려움과 연결되지만 단순히 의학적인 언어장애를 확정하는 문구는 아니다. 자신의 말이 사명을 감당하기에 부적합하다는 모세의 인식이 드러난다.","13절에서 하나님은 모세와 아론에게 명령하시며 이스라엘 자손을 애굽에서 인도하여 내도록 하신다. 구출의 약속이 백성의 낙담이나 모세의 자기 평가에 의존하지 않는다는 사실이 본문의 끝에서 다시 드러난다. 다음 계보와 소명 반복은 바로 이 두 사람을 역사 속에 자리매김하면서 이야기를 이어 간다."]}],"lexicalCards":[{"verse":6,"lemma":"גָּאַל","form":"וְגָאַלְתִּי","pronunciation":"베가알티","gloss":"내가 속량하겠다 — 하나님의 구원 행동"},{"verse":9,"lemma":"רוּחַ","form":"מִקֹּצֶר רוּחַ","pronunciation":"미코체르 루아흐","gloss":"숨·마음의 짧음 — 고난으로 인한 낙담과 압박"},{"verse":12,"lemma":"עָרֵל","form":"עֲרַל שְׂפָתָיִם","pronunciation":"아랄 세파타임","gloss":"할례 받지 못한 입술 — 말의 부적합성을 호소하는 표현"}],"discoveries":[{"id":"exo6-2-5-disc","title":"나는 여호와라","paragraphs":["하나님의 첫마디는 '나는 여호와라'이다. 앞서 모세가 하나님의 이름을 들은 장면(3:13–15)을 기억하면, 여기서 하나님은 새로운 신의 이름을 처음 소개하는 것이 아니다. 처음부터 모세를 부르셨던 분이 바로 그분임을 다시 확인하시는 것이다. 구출의 기미가 보이지 않는 가운데 이름의 자기 선언이 앞에 놓인 까닭은 이스라엘이 겪고 있는 현실보다 하나님의 정체성이 약속의 기반이라는 데 있다."]},{"id":"exo6-6-8-disc","title":"내가 너희를 인도하여 내리라","paragraphs":["하나님은 모세에게 이스라엘 자손에게 전할 말씀을 주신다. 이 단락에는 '내가'라는 주어를 중심으로 구원 행동의 동사들이 연속한다. 하나님이 노역에서 '빼내고', 종살이에서 '건지고', 편 팔과 큰 심판으로 '속량하며', 그들을 자신의 백성으로 '삼고', 그들의 하나님이 되고, 약속의 땅으로 '인도하여' 주실 것이라는 말씀이다. 구출은 단순한 장소 이동이 아니라 누구에게 속한 백성으로 살 것인가를 바꾸는 사건이다."]},{"id":"exo6-9-13-disc","title":"듣지 못하는 백성과 다시 보내심을 받은 모세","paragraphs":["모세는 명령대로 말씀을 전하지만 이스라엘 자손은 듣지 않는다. 성경은 그 이유를 '마음의 상함과 가혹한 노역'에 둔다. 히브리어 미코체르 루아흐(מִקֹּצֶר רוּחַ, 미코체르 루아흐)는 문자적으로 '영/숨의 짧음에서'라는 표현으로, 숨 막히는 압박과 낙담의 상태를 묘사한다. 백성이 언약을 저버렸다는 판결을 이 문장에 덧씌우기보다, 극심한 고통 가운데 희망의 소식조차 받아들이기 어려운 현실을 읽어야 한다."]}],"canonicalLinks":[{"ref":"출애굽기 3:12–15","note":"하나님의 이름과 동행 약속이 언약의 성취 선언으로 이어진다"},{"ref":"창세기 15:13–21","note":"압제와 귀환의 약속이 구출 사건과 연결된다"},{"ref":"창세기 17:7–8","note":"하나님과 백성의 언약 관계와 땅의 약속"},{"ref":"출애굽기 2:23–25","note":"탄식과 언약 기억이 하나님의 구출 선언으로 전개된다"},{"ref":"출애굽기 19:4–6","note":"구원받은 백성의 정체성과 사명으로 발전한다"}],"theologicalSynthesis":["출애굽기 3:12–15의 동행과 이름 계시는 6:2–8에서 언약과 구원의 약속으로 더욱 선명하게 전개된다. 창세기 15:13–21의 이방 땅 압제와 귀환 약속, 창세기 17:7–8의 하나님과 백성의 관계, 출애굽기 2:23–25의 탄식과 언약 기억은 이 단락과 직접 연결되는 주요 본문이다. 레위기 26:12의 언약적 관계 공식은 '내가 너희 하나님이 되리라'는 주제의 후속 전개이며, 출애굽기 19:4–6은 구출된 공동체의 소명으로 이어진다. 이 관계를 단순한 인용 목록이 아니라 약속에서 구원 행동으로, 구원 행동에서 백성의 정체성으로 이어지는 흐름으로 읽을 수 있다."],"relatedResearch":[],"readerSources":[{"name":"본문 직접 연구 초안","locator":"Exodus 6:2–13","license":"INTERNAL_CANDIDATE_ONLY"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"EXODUS_06_28_TO_07_07_READABLE_WORBS_v0.1_CANDIDATE","sourcePath":"G:\\내 드라이브\\Jude_Lee_OS\\01_PROJECTS\\01_목회연구_WORBS_BICS\\WORKING_COMMENTARY66_20261011\\EXODUS_06_28_TO_07_07_READABLE_WORBS_v0.1_CANDIDATE.md","sourceSha256":"62061110da7b17525e5a1f8a0a05af62e5b30e2de4cf0ef84b430093cf5f6920","passage":{"book":"exo","chapter":6,"chapterEnd":7,"v1":28,"v2":7,"ref":"출애굽기 6:28–7:7"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"입술이 무겁다는 모세를 다시 보내시다","overview":["계보의 끝에서 이야기는 다시 모세의 두려움으로 돌아간다. 모세는 하나님이 하신 말씀을 바로에게 전해야 하지만 자신의 말이 제대로 전달될 수 있을지 확신하지 못한다. 하나님은 모세의 말솜씨가 충분하다고 칭찬하여 문제를 풀지 않으신다. 대신 아론과 함께 수행할 사명을 구체적으로 정하시며, 바로가 듣지 않는 현실까지 구원의 역사 안에서 설명하신다. 출애굽의 시작은 뛰어난 연설가가 만들어 낸 성과가 아니라 여호와의 말씀과 행동으로 나타날 사건이다."],"centralMessage":"계보의 끝에서 이야기는 다시 모세의 두려움으로 돌아간다. 모세는 하나님이 하신 말씀을 바로에게 전해야 하지만 자신의 말이 제대로 전달될 수 있을지 확신하지 못한다. 하나님은 모세의 말솜씨가 충분하다고 칭찬하여 문제를 풀지 않으신다. 대신 아론과 함께 수행할 사명을 구체적으로 정하시며, 바로가 듣지 않는 현실까지 구원의 역사 안에서 설명하신다. 출애굽의 시작은 뛰어난 연설가가 만들어 낸 성과가 아니라 여호와의 말씀과 행동으로 나타날 사건이다.","literaryStructure":[{"v1":28,"v2":30,"title":"다시 들리는 사명의 말"},{"v1":1,"v2":2,"title":"모세와 아론의 나누어진 역할"},{"v1":3,"v2":5,"title":"듣지 않는 바로와 큰 심판"},{"v1":6,"v2":7,"title":"명령대로 행한 두 형제"}],"sections":[{"id":"exo6-28-30","v1":28,"v2":30,"title":"다시 들리는 사명의 말","paragraphs":["6장 10–12절에 이미 나타난 대화가 계보 뒤에서 다시 울린다. 여호와께서는 모세에게 애굽 왕 바로에게 자신이 하신 말씀을 모두 전하라고 명령하신다. 모세는 자신의 '할례 받지 못한 입술'을 다시 언급하며 바로가 어떻게 자기 말을 듣겠느냐고 묻는다. 이 반복은 본문이 실수로 같은 장면을 중복했다는 판단으로 곧장 끝낼 수 없다. 지금의 이야기 배열에서 계보 앞뒤의 두 대화는 모세와 아론의 정체성과 사명을 이어 주는 문학적 고리로 기능한다.","모세의 문제는 막연히 사람 앞에서 긴장한다는 정도를 넘어선다. 이스라엘 자손도 그의 말을 듣지 않는 형편인데 이집트 왕이 왜 들어 주겠느냐는 것이다. 하나님이 주신 말씀과 그것을 듣지 않는 사람들의 반응 사이에 선 모세의 어려움은 구출 사건의 시작에서 실제 긴장이 된다."]},{"id":"exo7-1-2","v1":1,"v2":2,"title":"모세와 아론의 나누어진 역할","paragraphs":["여호와는 모세에게 자신이 그를 바로에게 '하나님 같이' 되게 하였으며 형 아론이 그의 대언자가 되리라고 말씀하신다. 이 표현은 모세가 본질적으로 신이 된다는 뜻이 아니다. 하나님이 모세에게 위임하신 권위와 모세의 말을 전달할 아론의 역할을 보여 준다. 출애굽기 4:15–16에서도 모세와 아론의 말 전달 관계가 이미 설명되었다.","모세는 하나님의 말씀을 받아 전하고 아론은 그 말을 바로에게 전한다. 이 명령은 모세가 말하기의 불완전함을 이미 극복했다는 선언이 아니라, 부족함을 가진 사람에게도 수행할 구조가 주어진다는 사실을 드러낸다. 구원의 메시지는 모세의 창의적인 정치적 제안이 아니라 여호와의 명령에서 나온다."]},{"id":"exo7-3-5","v1":3,"v2":5,"title":"듣지 않는 바로와 큰 심판","paragraphs":["하나님은 바로가 쉽게 듣지 않을 것이라고 미리 말씀하신다. 바로의 마음이 완고해지는 문제와 하나님이 그 마음을 완고하게 하신다는 진술은 출애굽 서사를 읽을 때 중요한 신학적 쟁점이다. 이 단락만으로 바로의 모든 책임과 하나님의 주권을 설명하는 철학적 체계를 끝낼 수는 없다. 이어지는 재앙 이야기에는 바로 자신의 완고함과 하나님의 역사에 관한 서로 다른 서술이 함께 나타난다. 각 문장의 주어와 시점을 추적하면서 읽는 것이 중요하다.","그럼에도 3–5절의 중심 목적은 뚜렷하다. 하나님은 애굽 가운데 표징과 기사를 많게 하시고 큰 심판으로 이스라엘을 인도하여 내실 것이다. '애굽 사람이 나를 여호와인 줄 알리라'는 선언은 6:7의 이스라엘이 여호와를 알게 된다는 약속과 짝을 이룬다. 하나님을 아는 지식은 이 사건에서 추상적 정의에 머무르지 않고 구출과 심판 속에서 드러난다."]},{"id":"exo7-6-7","v1":6,"v2":7,"title":"명령대로 행한 두 형제","paragraphs":["본문은 모세와 아론이 여호와께서 명령하신 대로 행하였다는 짧은 문장으로 마무리된다. 여기서는 아직 재앙이 시작되지 않았다. 그러나 거듭된 질문과 주저가 명령을 이행하는 움직임으로 전환되었다. 뒤이어 두 사람의 나이가 기록된다. 모세는 여든, 아론은 여든셋이었다. 나이의 기록은 이제 시작될 구출의 이야기가 추상적인 신화적 상징만이 아니라 본문 속 인물의 생애에 연결되어 제시됨을 강조한다. 이 수치를 근거 없이 현대식 연대표 전체의 절대연대로 환산해서는 안 된다."]}],"lexicalCards":[],"discoveries":[{"id":"exo6-28-30-disc","title":"다시 들리는 사명의 말","paragraphs":["6장 10–12절에 이미 나타난 대화가 계보 뒤에서 다시 울린다. 여호와께서는 모세에게 애굽 왕 바로에게 자신이 하신 말씀을 모두 전하라고 명령하신다. 모세는 자신의 '할례 받지 못한 입술'을 다시 언급하며 바로가 어떻게 자기 말을 듣겠느냐고 묻는다. 이 반복은 본문이 실수로 같은 장면을 중복했다는 판단으로 곧장 끝낼 수 없다. 지금의 이야기 배열에서 계보 앞뒤의 두 대화는 모세와 아론의 정체성과 사명을 이어 주는 문학적 고리로 기능한다."]},{"id":"exo7-1-2-disc","title":"모세와 아론의 나누어진 역할","paragraphs":["여호와는 모세에게 자신이 그를 바로에게 '하나님 같이' 되게 하였으며 형 아론이 그의 대언자가 되리라고 말씀하신다. 이 표현은 모세가 본질적으로 신이 된다는 뜻이 아니다. 하나님이 모세에게 위임하신 권위와 모세의 말을 전달할 아론의 역할을 보여 준다. 출애굽기 4:15–16에서도 모세와 아론의 말 전달 관계가 이미 설명되었다."]},{"id":"exo7-3-5-disc","title":"듣지 않는 바로와 큰 심판","paragraphs":["하나님은 바로가 쉽게 듣지 않을 것이라고 미리 말씀하신다. 바로의 마음이 완고해지는 문제와 하나님이 그 마음을 완고하게 하신다는 진술은 출애굽 서사를 읽을 때 중요한 신학적 쟁점이다. 이 단락만으로 바로의 모든 책임과 하나님의 주권을 설명하는 철학적 체계를 끝낼 수는 없다. 이어지는 재앙 이야기에는 바로 자신의 완고함과 하나님의 역사에 관한 서로 다른 서술이 함께 나타난다. 각 문장의 주어와 시점을 추적하면서 읽는 것이 중요하다."]},{"id":"exo7-6-7-disc","title":"명령대로 행한 두 형제","paragraphs":["본문은 모세와 아론이 여호와께서 명령하신 대로 행하였다는 짧은 문장으로 마무리된다. 여기서는 아직 재앙이 시작되지 않았다. 그러나 거듭된 질문과 주저가 명령을 이행하는 움직임으로 전환되었다. 뒤이어 두 사람의 나이가 기록된다. 모세는 여든, 아론은 여든셋이었다. 나이의 기록은 이제 시작될 구출의 이야기가 추상적인 신화적 상징만이 아니라 본문 속 인물의 생애에 연결되어 제시됨을 강조한다. 이 수치를 근거 없이 현대식 연대표 전체의 절대연대로 환산해서는 안 된다."]}],"canonicalLinks":[{"ref":"출애굽기 4:10–16","note":"모세의 말하기 어려움과 아론의 역할"},{"ref":"출애굽기 6:2–8","note":"하나님의 이름과 구출 약속"},{"ref":"출애굽기 14:4, 18","note":"여호와를 알게 된다는 주제의 발전"}],"theologicalSynthesis":["출애굽기 4:10–16의 말하기 어려움과 아론의 대변 역할이 6:28–7:2에서 다시 나타난다. 6:2–8의 '나는 여호와라'는 7:5에서 애굽도 여호와를 알게 되리라는 선언으로 확장된다. 출애굽기 9:16은 바로와 하나님의 이름이 세상에 알려지는 문제를 더욱 분명히 다룬다. 출애굽기 14:4, 14:18도 여호와를 아는 주제를 후속 구출 사건과 연결한다."],"relatedResearch":[],"readerSources":[{"name":"본문 직접 연구 초안","locator":"Exodus 6:28–7:7","license":"INTERNAL_CANDIDATE_ONLY"}]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_EXODUS_07_08_13_WORBS_V02_20261013","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/13시대_인물사건_관계연구/JBC_EXODUS_07_08_13_WORBS_V02_20261013.md","sourceSha256":"6d003464a4820fe61b01f34c4aa7817e7a1da368816832ce13cc2ac35e73d8ed","passage":{"book":"exo","chapter":7,"v1":8,"v2":13,"ref":"출애굽기 7:8–13"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"PROFESSIONAL_RESEARCH_PASS","qualityStatus":"PASS_WITH_VERIFY","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"삼킨 지팡이 앞에서도 닫힌 귀","overview":["하나님 말씀에 따라 아론이 지팡이를 던지고, 애굽의 마술사들도 유사한 표징을 보인다. 아론의 지팡이는 다른 지팡이들을 삼키지만 바로는 듣지 않는다."],"centralMessage":"하나님의 명령에 따라 아론의 지팡이가 다른 지팡이들을 삼키는 표징이 나타났지만 바로는 말씀을 듣지 않았다. 이 단락은 표징의 우세와 왕의 완고한 거절을 함께 보여 준다.","literaryStructure":[{"title":"표징을 준비시키는 말씀과 실행","v1":8,"v2":10},{"title":"애굽의 지혜자들과 마술사들의 대응","v1":11,"v2":12},{"title":"아론의 지팡이가 삼키는 역전","v1":12,"v2":12},{"title":"완고하여 듣지 않는 바로","v1":13,"v2":13}],"sections":[{"id":"exo7-1","v1":8,"v2":10,"title":"첫 번째 이야기 — 바로가 요구할 기적 (8–10절)","paragraphs":["모세와 아론이 바로 앞에 서기 전에 하나님은 그들에게 한 가지 일을 준비시키신다. 바로가 자신들의 말을 믿을 만한 기적을 보여 달라고 요구하면, 아론이 지팡이를 던지게 하라는 것이다.","하나님이 먼저 일러 주시는 이 말씀을 기억하면, 바로의 궁정에서 이어질 장면이 다르게 보인다. 모세와 아론은 난처한 요구 앞에서 급히 기적을 만들어 내야 할 사람들이 아니다. 그들이 해야 할 일은 이미 받은 말씀을 따라 행동하는 것이다.","그들은 바로에게 나아갔다. 아론이 지팡이를 던지자 그것이 뱀이 되었다. 앞서 모세가 광야에서 경험했던 지팡이의 표징을 떠올리게 하는 장면이다(출 4:1–5). 다만 이곳의 히브리어는 출애굽기 4장의 일반적인 '뱀'이라는 말과 다른 '탄닌'이라는 단어를 사용한다. 번역에서 뱀으로 옮기더라도, 단어의 차이까지 지워 버릴 필요는 없다.","본문은 아론의 지팡이가 어떤 원리로 변했는지를 설명하지 않는다. 대신 하나님의 명령이 있었고, 모세와 아론이 그대로 행했으며, 그 결과가 바로 앞에 나타났다고 전한다. 왕의 요구가 이야기의 출발점처럼 보이지만 실제 사건의 주도권은 이미 하나님의 말씀 안에 있다."]},{"id":"exo7-2","v1":11,"v2":12,"title":"두 번째 이야기 — 바로도 사람들을 부르다 (11–12절 상반)","paragraphs":["바로는 그 광경 앞에서 바로 뜻을 굽히지 않는다. 그는 애굽의 지혜자들과 마술사들을 부른다.","그들도 지팡이를 던졌다. 그리고 본문은 그들의 지팡이도 뱀이 되었다고 말한다. 이 대목을 읽으면서 독자는 쉽게 '어떻게 그런 일이 가능했을까?' 하고 묻게 된다. 하지만 성경은 여기서 그들이 사용한 기술이나 비밀의 모든 내용을 밝혀 주지 않는다. 속임수였는지, 어떤 다른 힘이 작용했는지를 본문이 말하지 않은 방식으로 단정하면 이야기의 초점이 옮겨진다.","더 중요한 것은 바로의 반응이다. 그는 자신 앞에 나타난 표징을 보고 판단하는 대신, 자신의 궁정이 가진 지혜와 비술을 동원하여 맞선다. 아론의 지팡이와 마술사들의 지팡이가 같은 자리에 놓이면서, 이제 독자는 그 두 표징이 어떤 관계에 있는지 보게 된다."]},{"id":"exo7-3","v1":12,"v2":12,"title":"세 번째 이야기 — 하나의 지팡이가 다른 지팡이들을 삼키다 (12절 하반)","paragraphs":["바로 그때 짧은 문장이 사건의 방향을 바꾼다.","아론의 지팡이가 그들의 지팡이들을 삼켰다.","서술은 길지 않다. 그런데도 이 한 문장이 앞서 형성된 대치의 결과를 결정한다. 궁정의 마술사들은 비슷한 장면을 보여 줄 수 있었지만, 아론의 지팡이가 그들의 지팡이들을 삼키는 것을 막지 못한다.","성경은 여기서 모세와 아론이 더 뛰어난 마술사라는 결론으로 독자를 이끌지 않는다. 그들은 자기 능력을 겨루려고 온 사람들이 아니라 하나님의 명령을 전하도록 보내진 사람들이다. 표징의 우세는 왕의 궁정보다 크신 하나님의 주도권을 드러내는 방식으로 기능한다.","그러나 독자가 기대할 법한 일, 곧 바로가 그 표징을 보고 결국 하나님의 말씀을 듣게 되는 일은 이어지지 않는다."]},{"id":"exo7-4","v1":13,"v2":13,"title":"네 번째 이야기 — 보아도 듣지 않는 마음 (13절)","paragraphs":["아론의 지팡이는 다른 지팡이들을 삼켰다. 그럼에도 바로의 마음은 강퍅해졌고 그는 모세와 아론의 말을 듣지 않았다.","이 결말에는 낯선 긴장이 있다. 표징은 모호하게 끝나지 않았지만, 바로의 반응도 바뀌지 않았다. 사건의 우열이 드러나는 일과 사람이 말씀을 듣는 일은 똑같은 일이 아닌 것이다.","출애굽기 앞부분에서 하나님은 바로가 쉽게 백성을 보내지 않을 것을 이미 말씀하셨다(출 7:1–7). 이제 독자는 그 예고가 실제 장면에서 어떤 모습으로 나타나는지 본다. 바로는 지팡이들의 결과를 보았지만, 그 결과를 따라 하나님이 요구하시는 말씀에 순종하지는 않는다.","따라서 이 단락은 단순한 기적 대결의 승리담으로 끝나지 않는다. **하나님의 말씀은 바로의 궁정 앞에서도 그 권위를 드러내지만, 그 말씀을 듣기를 거절하는 왕의 마음은 여전히 닫혀 있다.** 뒤이어 시작되는 재앙의 이야기는 바로 이 거절 뒤에서 전개된다."]}],"lexicalCards":[{"verse":9,"form":"תַּנִּין","lemma":"תַּנִּין","pronunciation":"탄닌 (tannîn)","gloss":"큰 뱀·파충류적 생물. 출 4:3의 נָחָשׁ(나하쉬)와 다른 어휘이며 현대 동물 종은 확정할 수 없다."},{"verse":12,"form":"וַיִּבְלַע","lemma":"בָּלַע","pronunciation":"발라 (bālaʿ)","gloss":"삼키다. 아론의 지팡이가 다른 지팡이들을 압도하는 사건의 동사이다."},{"verse":13,"form":"וַיֶּחֱזַק","lemma":"חָזַק","pronunciation":"하자크 (ḥāzaq)","gloss":"강해지다·완고해지다. 바로의 마음이 굳어져 듣지 않았다는 결말을 표현한다."}],"discoveries":[{"id":"exo7-8-13-d1","domain":"literary","title":"표징의 우세와 왕의 거절","paragraphs":["아론의 지팡이가 다른 지팡이를 삼켰지만 바로는 듣지 않았다. 표징과 경청을 구별한다."]}],"canonicalLinks":[{"ref":"출애굽기 4:1–5","note":"지팡이 표징의 선행 장면과 비교하되 뱀 어휘의 차이를 구별한다."},{"ref":"출애굽기 7:1–7","note":"하나님의 명령과 바로의 완고함에 대한 예고가 이어진다."},{"ref":"출애굽기 7:14–25","note":"왕의 거절 이후 첫 재앙의 서사가 시작된다."}],"theologicalSynthesis":["아론의 지팡이가 애굽 마술사들의 지팡이를 삼키는 장면은 하나님의 명령으로 나타난 표징의 우세를 드러낸다. 그러나 표징의 결과를 본 바로는 여전히 듣지 않는다. 본문은 표징이 작동한 비밀을 설명하는 대신 하나님의 말씀, 모세와 아론의 순종, 왕의 거절을 대비한다. תַּנִּין(탄닌)은 출애굽기 4:3의 נָחָשׁ(나하쉬)와 다른 어휘이며, חָזַק(하자크) 계열의 완고함은 7:13에서 바로가 듣지 않았다는 결과와 함께 읽어야 한다. 이 한 절만으로 완고함의 모든 원인과 책임을 단정하지 않는다."],"relatedResearch":[],"readerSources":[],"professionalReviewStatus":"APPROVED_DOWNSTREAM_PROJECTION"}].forEach(function(r){a.push(r);});if(w.JBCResearch&&w.JBCResearch._done)w.JBCResearch._done("exo");})(window);
